//TODO
contract record Mercata is Authorizable {
    RateStrategy public rateStrategy;
    PriceOracle public priceOracle;
    CollateralVault public collateralVault;
    LiquidityPool public liquidityPool;
    LendingPool public lendingPool;
    PoolConfigurator public poolConfigurator;
    LendingRegistry public lendingRegistry;
    MercataBridge public mercataBridge;
    PoolFactory public poolFactory;
    TokenFactory public tokenFactory;
    FeeCollector public feeCollector;
    AdminRegistry public adminRegistry;
    CDPEngine public cdpEngine;
    CDPVault public cdpVault;
    CDPRegistry public cdpRegistry;
    CDPReserve public cdpReserve;
    SafetyModule public safetyModule;
    RewardsChef public rewardsChef;

    constructor() public {
        // The owner of the implementation contract is ignored in favor of the proxy owner
        address implOwnerIgnored = address("deadbeef");

        // Create AdminRegistry first
        address adminRegistryImpl = address(new AdminRegistry());
        adminRegistry = AdminRegistry(address(new Proxy(adminRegistryImpl, this)));
        adminRegistry.initialize([this]); // Mercata contract is temporarily the sole admin
        Ownable(address(adminRegistry)).transferOwnership(address(adminRegistry));

        // Create FeeCollector
        address feeCollectorImpl = address(new FeeCollector(implOwnerIgnored));
        feeCollector = FeeCollector(address(new Proxy(feeCollectorImpl, this)));
        Ownable(feeCollector).transferOwnership(address(adminRegistry));

        // Create Factories
        address tokenFactoryImpl = address(new TokenFactory(implOwnerIgnored));
        tokenFactory = TokenFactory(address(new Proxy(tokenFactoryImpl, this)));
        Ownable(tokenFactory).transferOwnership(address(adminRegistry));

        address poolFactoryImpl = address(new PoolFactory(implOwnerIgnored));
        poolFactory = PoolFactory(address(new Proxy(poolFactoryImpl, this)));
        poolFactory.initialize(address(tokenFactory), address(adminRegistry), address(feeCollector));
        Ownable(poolFactory).transferOwnership(address(adminRegistry));
        adminRegistry.castVoteOnIssue(address(adminRegistry), "addWhitelist", address(tokenFactory), "createTokenWithInitialOwner", address(poolFactory));

        // Create Lending related contracts
        address lendingRegistryImpl = address(new LendingRegistry(implOwnerIgnored));
        lendingRegistry = LendingRegistry(address(new Proxy(lendingRegistryImpl, this)));
        Ownable(lendingRegistry).transferOwnership(address(adminRegistry));

        address collateralVaultImpl = address(new CollateralVault(implOwnerIgnored));
        collateralVault = CollateralVault(address(new Proxy(collateralVaultImpl, this)));
        collateralVault.initialize(address(lendingRegistry));
        Ownable(collateralVault).transferOwnership(address(adminRegistry));

        address liquidityPoolImpl = address(new LiquidityPool(implOwnerIgnored));
        liquidityPool = LiquidityPool(address(new Proxy(liquidityPoolImpl, this)));
        liquidityPool.initialize(address(lendingRegistry));
        Ownable(liquidityPool).transferOwnership(address(adminRegistry));

        address rateStrategyImpl = address(new RateStrategy());
        rateStrategy = RateStrategy(address(new Proxy(rateStrategyImpl, this)));
        Ownable(address(rateStrategy)).transferOwnership(address(adminRegistry));

        address priceOracleImpl = address(new PriceOracle(implOwnerIgnored));
        priceOracle = PriceOracle(address(new Proxy(priceOracleImpl, this)));
        Ownable(priceOracle).transferOwnership(address(adminRegistry));

        address poolConfiguratorImpl = address(new PoolConfigurator(implOwnerIgnored));
        poolConfigurator = PoolConfigurator(address(new Proxy(poolConfiguratorImpl, this)));
        poolConfigurator.initialize(address(lendingRegistry));
        Ownable(poolConfigurator).transferOwnership(address(adminRegistry));

        address safetyModuleImpl = address(new SafetyModule(implOwnerIgnored));
        safetyModule = SafetyModule(address(new Proxy(safetyModuleImpl, this)));
        safetyModule.initialize(address(lendingRegistry), address(tokenFactory));
        Ownable(safetyModule).transferOwnership(address(adminRegistry));

        address lendingPoolImpl = address(new LendingPool(implOwnerIgnored));
        lendingPool = LendingPool(address(new Proxy(lendingPoolImpl, this)));
        lendingPool.initialize(address(lendingRegistry), address(poolConfigurator), address(tokenFactory), address(feeCollector), address(safetyModule));
        Ownable(lendingPool).transferOwnership(address(adminRegistry));

        adminRegistry.castVoteOnIssue(address(adminRegistry), "addWhitelist", address(lendingRegistry), "setLendingPool", address(poolConfigurator));
        adminRegistry.castVoteOnIssue(address(adminRegistry), "addWhitelist", address(lendingRegistry), "setLiquidityPool", address(poolConfigurator));
        adminRegistry.castVoteOnIssue(address(adminRegistry), "addWhitelist", address(lendingRegistry), "setCollateralVault", address(poolConfigurator));
        adminRegistry.castVoteOnIssue(address(adminRegistry), "addWhitelist", address(lendingRegistry), "setRateStrategy", address(poolConfigurator));
        adminRegistry.castVoteOnIssue(address(adminRegistry), "addWhitelist", address(lendingRegistry), "setPriceOracle", address(poolConfigurator));
        adminRegistry.castVoteOnIssue(address(adminRegistry), "addWhitelist", address(lendingRegistry), "setAllComponents", address(poolConfigurator));
        authorizations[address(adminRegistry)][address(poolConfigurator)] = 1;
        poolConfigurator.initializeProtocol(address(lendingPool),address(liquidityPool),address(collateralVault),address(rateStrategy),address(priceOracle),address(tokenFactory),[],[],[],[],[],[],[],0,0,1000);

        // Create Services
        address mercataBridgeImpl = address(new MercataBridge(implOwnerIgnored));
        mercataBridge = MercataBridge(address(new Proxy(mercataBridgeImpl, this)));
        mercataBridge.initialize(address(tokenFactory));
        Ownable(mercataBridge).transferOwnership(address(adminRegistry));

        // Create RewardsChef (without initialization - to be initialized in tests)
        address rewardsChefImpl = address(new RewardsChef(implOwnerIgnored));
        rewardsChef = RewardsChef(address(new Proxy(rewardsChefImpl, this)));
        Ownable(rewardsChef).transferOwnership(address(adminRegistry));

        // Deploy CDP registry, vault, and engine
        address cdpRegistryImpl = address(new CDPRegistry(implOwnerIgnored));
        cdpRegistry = CDPRegistry(address(new Proxy(cdpRegistryImpl, this)));

        address cdpVaultImpl = address(new CDPVault(implOwnerIgnored));
        cdpVault = CDPVault(address(new Proxy(cdpVaultImpl, this)));
        cdpVault.initialize(address(cdpRegistry));
        Ownable(cdpVault).transferOwnership(address(adminRegistry));

        address cdpEngineImpl = address(new CDPEngine(implOwnerIgnored));
        cdpEngine = CDPEngine(address(new Proxy(cdpEngineImpl, this)));
        cdpEngine.initialize(address(cdpRegistry));
        Ownable(cdpEngine).transferOwnership(address(adminRegistry));

        address cdpReserveImpl = address(new CDPReserve(implOwnerIgnored));
        cdpReserve = CDPReserve(address(new Proxy(cdpReserveImpl, this)));
        cdpReserve.initialize(address(cdpRegistry));
        Ownable(cdpReserve).transferOwnership(address(adminRegistry));

        cdpRegistry.setAllComponents(address(cdpVault), address(cdpEngine), address(priceOracle), address(0x937efa7e3a77e20bbdbd7c0d32b6514f368c1010), address(tokenFactory), address(feeCollector), address(cdpReserve));
        Ownable(cdpRegistry).transferOwnership(address(adminRegistry));

        adminRegistry.swapAdmin(this, msg.sender);
    }
}

import "../../abstract/ERC20/access/Ownable.sol";
import "../../abstract/ERC20/IERC20.sol";
import "../../abstract/ERC20/utils/StringUtils.sol";
import "../Tokens/TokenFactory.sol";
import "../Tokens/Token.sol";
import "../Admin/AdminRegistry.sol";
import "../../libraries/Bridge/BridgeTypes.sol";

/**
 * @title MercataBridge
 * @dev Complete bridge system for STRATO <-> External EVM value tunnel
 * @notice Manages deposit and withdrawal workflows with decimal conversion
 * @notice Implements the core logic for cross-chain token bridging
 * @notice Supports multiple external chains and token configurations
 */
contract record MercataBridge is Ownable {
    /// @notice Enables BridgeTypes library functions for all types
    /// @dev Allows direct access to BridgeTypes utility functions without explicit library calls
    using BridgeTypes for *;
    using StringUtils for string;

    /* ===================================================================== */
    /*                                EVENTS                                 */
    /* ===================================================================== */

    // ───────────── Admin related events ─────────────
    /// @notice Emitted when pause states are toggled for deposits and withdrawals
    event PauseToggled(bool depositsPaused, bool withdrawalsPaused);

    /// @notice Emitted when the token factory address is updated
    event TokenFactoryUpdated(address newFactory, address oldFactory);

    /// @notice Emitted when the USDST address is updated
    event USDSTAddressUpdated(address newAddress, address oldAddress);

    /// @notice Emitted when a chain's enabled state is toggled
    event ChainToggled(bool enabled, uint256 externalChainId);

    /// @notice Emitted when an asset's enabled state is toggled
    event AssetToggled(bool enabled, uint256 externalChainId, address externalToken);

    // ───────────── Deposit & withdrawal related events ─────────────
    /// @notice Emitted when a deposit is aborted by the owner
    event DepositAborted(uint256 srcChainId, string srcTxHash);

    /// @notice Emitted when a deposit is completed and tokens are minted
    event DepositCompleted(uint256 srcChainId, string srcTxHash);

    /// @notice Emitted when a deposit is initiated
    /// @param externalChainId The external chain identifier where the deposit occurred
    /// @param externalSender The address that sent the transaction on the external chain
    /// @param externalTxHash The transaction hash on the external chain
    /// @param stratoRecipient The STRATO address to receive the minted tokens
    /// @param stratoToken The STRATO token address that will be minted
    /// @param stratoTokenAmount The amount of STRATO tokens to be minted
    event DepositInitiated(uint256 externalChainId, address externalSender, string externalTxHash, address stratoRecipient, address stratoToken, uint256 stratoTokenAmount);

    /// @notice Emitted when a deposit requires manual review
    event DepositPendingReview(uint256 srcChainId, string srcTxHash);

    /// @notice Emitted when a withdrawal is aborted and funds are refunded
    event WithdrawalAborted(uint256 withdrawalId);

    /// @notice Emitted when a withdrawal is completed and tokens are burned
    event WithdrawalCompleted(uint256 withdrawalId);

    /// @notice Emitted when a withdrawal is pending custody transaction
    event WithdrawalPending(string custodyTxHash, uint256 withdrawalId);

    /// @notice Emitted when a user requests a withdrawal
    /// @param dest The external recipient address on the destination chain
    /// @param destChainId The external chain identifier where tokens should be sent
    /// @param externalTokenAmount The amount of external tokens to be sent
    /// @param stratoTokenAmount The amount of STRATO tokens escrowed
    /// @param token The STRATO token address that was escrowed
    /// @param user The address that requested the withdrawal
    /// @param withdrawalId The unique withdrawal identifier
    event WithdrawalRequested(address dest, uint256 destChainId, uint256 externalTokenAmount, uint256 stratoTokenAmount, address token, address user, uint256 withdrawalId);

    // ───────────── Registry related events ─────────────
    /// @notice Emitted when chain configuration is updated
    event ChainUpdated(string chainName, address custody, bool enabled, uint256 externalChainId, uint256 lastProcessedBlock, address router);

    /// @notice Emitted when the last processed block is updated for a chain
    event LastProcessedBlockUpdated(uint256 externalChainId, uint256 lastProcessedBlock);

    /// @notice Emitted during emergency block rollback operations
    event EmergencyBlockRollback(uint256 externalChainId, uint256 lastProcessedBlock);

    /// @notice Emitted when asset configuration is updated for a chain
    /// @param enabled Whether the asset is enabled for bridge operations
    /// @param externalChainId The external chain identifier
    /// @param externalDecimals The number of decimals for the external token
    /// @param externalName The name of the external token
    /// @param externalSymbol The symbol of the external token
    /// @param externalToken The address of the external token contract
    /// @param maxPerWithdrawal Maximum amount per withdrawal (0 = unlimited)
    /// @param stratoToken The corresponding STRATO token address
    event AssetUpdated(bool enabled, uint256 externalChainId, uint256 externalDecimals, string externalName, string externalSymbol, address externalToken, uint256 maxPerWithdrawal, address stratoToken);

    /* ===================================================================== */
    /*                            STATE VARIABLES                            */
    /* ===================================================================== */
    // ───────────── Admin related state variables ─────────────
    /// @notice Standard decimal places for STRATO tokens
    /// @dev Default: 18 decimals for all STRATO tokens
    /// @dev Used for decimal conversion between external tokens and STRATO tokens
    uint256 public DECIMAL_PLACES = 18;

    /// @notice Circuit breaker for deposit operations
    /// @dev When true, all deposit operations are paused
    bool public depositsPaused;

    /// @notice Token factory contract for creating new STRATO tokens
    /// @dev Single source of truth for active token creation
    address public tokenFactory;

    /// @notice USDST token address for cross-chain minting/redeeming
    /// @dev Default USDST address: 0x937efa7e3a77e20bbdbd7c0d32b6514f368c1010
    address public USDST_ADDRESS = address(0x937efa7e3a77e20bbdbd7c0d32b6514f368c1010);

    /// @notice Circuit breaker for withdrawal operations
    /// @dev When true, all withdrawal operations are paused
    bool public withdrawalsPaused;

    /// @notice Time delay before users can abort stuck withdrawals
    /// @dev Default: 172800 seconds (48 hours)
    uint256 public WITHDRAWAL_ABORT_DELAY = 172800;

    // ───────────── Deposit & withdrawal related state variables ─────────────
    /// @notice Registry of deposit transactions with replay protection
    /// @dev Maps external chain ID and transaction hash to deposit information
    /// @dev Key: (externalChainId, externalTxHash) -> Value: DepositInfo struct
    /// @dev Prevents duplicate processing of the same external transaction
    /// @dev Stores deposit state and conversion information
    mapping(uint256 => mapping(string => DepositInfo)) public record deposits;

    /// @notice Registry of withdrawal requests by withdrawal ID
    /// @dev Maps withdrawal ID to withdrawal information
    /// @dev Key: withdrawalId (uint256) -> Value: WithdrawalInfo struct
    mapping(uint256 => WithdrawalInfo) public record withdrawals;

    /// @notice Auto-incrementing counter for withdrawal IDs
    /// @dev Ensures unique withdrawal identifiers for each request
    uint256 public withdrawalCounter;

    // ───────────── Registry related state variables ─────────────
    /// @notice Registry of external chains and their configuration
    /// @dev Maps external chain ID to chain information including custody, router, and processing state
    /// @dev Key: externalChainId (uint256) -> Value: ChainInfo struct
    mapping(uint256 => ChainInfo) public record chains;

    /// @notice Registry of assets for each external chain
    /// @dev Maps external token address and chain ID to asset configuration
    /// @dev Key: (externalToken address, externalChainId) -> Value: AssetInfo struct
    /// @dev Used to configure token mappings between external chains and STRATO
    /// @dev Includes decimal conversion information for each token pair
    mapping(address => mapping(uint256 => AssetInfo)) public record assets;


    /* ===================================================================== */
    /*                            MODIFIERS                                  */
    /* ===================================================================== */
    /// @notice Ensures deposits are not paused
    /// @dev Prevents deposit operations when circuit breaker is active
    modifier whenDepositsOpen() {
        require(!depositsPaused, "MB: deposits paused");
        _;
    }

    /// @notice Ensures withdrawals are not paused
    /// @dev Prevents withdrawal operations when circuit breaker is active
    modifier whenWithdrawalsOpen() {
        require(!withdrawalsPaused, "MB: withdrawals paused");
        _;
    }

    /* ===================================================================== */
    /*                            FUNCTIONS                                  */
    /* ===================================================================== */
    // ───────────── Constructor related functions ─────────────
    /**
     * @dev Initializes the MercataBridge contract with the specified owner
     * @notice Sets up the bridge system with ownership and access control
     * @notice This is the main bridge contract that handles all cross-chain operations
     * @param _owner The address that will be set as the contract owner
     */
    constructor(
        address _owner
    ) Ownable(_owner) { }

    /**
     * @dev Initializes the bridge system with essential configuration
     * @notice Sets up token factory and default values for the bridge
     * @notice Must be called after deployment to configure the bridge properly
     * @notice Configures decimal places, USDST address, and withdrawal timeout
     * @param _tokenFactory The token factory contract address for creating STRATO tokens
     */
    function initialize(
        address _tokenFactory
    ) external onlyOwner {
        DECIMAL_PLACES = 18;
        USDST_ADDRESS = address(0x937efa7e3a77e20bbdbd7c0d32b6514f368c1010);
        WITHDRAWAL_ABORT_DELAY = 172800;

        require(_tokenFactory != address(0), "MB: zero");
        tokenFactory = _tokenFactory;
    }

    // ───────────── Admin related functions ─────────────
    /**
     * @dev Emergency function to set the last processed block for a chain
     * @notice Allows rollback of block processing state in emergency situations
     * @param externalChainId The external chain identifier
     * @param lastProcessedBlock The block number to set as last processed
     */
    function emergencySetLastProcessedBlock(
        uint256 externalChainId, uint256 lastProcessedBlock
    ) external onlyOwner {
        require(externalChainId > 0, "MB: invalid external chain id");
        ChainInfo chainInfo = chains[externalChainId];
        require(chainInfo.custody != address(0), "MB: chain missing");

        chainInfo.lastProcessedBlock = lastProcessedBlock;
        emit LastProcessedBlockUpdated(externalChainId, lastProcessedBlock);
        emit EmergencyBlockRollback(externalChainId, lastProcessedBlock);
    }

    /**
     * @dev Sets asset configuration for a specific external chain
     * @notice Maps external tokens to their STRATO equivalents with withdrawal limits
     * @notice Configures decimal conversion between external tokens and STRATO tokens
     * @param enabled Whether the asset is enabled for bridge operations
     * @param externalChainId The external chain identifier
     * @param externalDecimals The number of decimals for the external token (used for conversion)
     * @param externalName The name of the external token
     * @param externalSymbol The symbol of the external token
     * @param externalToken The address of the external token contract
     * @param maxPerWithdrawal Maximum amount per withdrawal (0 = unlimited)
     * @param stratoToken The corresponding STRATO token address
     */
    function setAsset(
        bool enabled, uint256 externalChainId, uint256 externalDecimals, string externalName, string externalSymbol, address externalToken, uint256 maxPerWithdrawal, address stratoToken
    ) external onlyOwner {
        require(chains[externalChainId].custody != address(0), "MB: chain missing");
        require(externalName.length > 0, "MB: invalid external name");
        require(externalSymbol.length > 0, "MB: invalid external symbol");
        require(stratoToken != address(0), "MB: invalid strato token");
        require(externalDecimals <= DECIMAL_PLACES, "MB: decimals exceed max");
        assets[externalToken][externalChainId] = AssetInfo(enabled, externalChainId, externalDecimals, externalName, externalSymbol, externalToken, maxPerWithdrawal, stratoToken);
        emit AssetUpdated(enabled, externalChainId, externalDecimals, externalName, externalSymbol, externalToken, maxPerWithdrawal, stratoToken);
    }

    /**
     * @dev Updates asset metadata (name and symbol) for an existing asset
     * @notice Only the owner can update asset metadata for existing assets
     * @notice Allows updating token display information without recreating the asset
     * @notice Validates that the asset exists before updating metadata
     * @param externalChainId The external chain identifier where the asset is configured
     * @param externalName The new name of the external token
     * @param externalSymbol The new symbol of the external token
     * @param externalToken The external token address to update
     */
    function setAssetMetadata(
        uint256 externalChainId, string externalName, string externalSymbol, address externalToken
    ) external onlyOwner {
        require(externalChainId > 0, "MB: invalid chain id");
        require(externalName.length > 0, "MB: invalid external name");
        require(externalSymbol.length > 0, "MB: invalid external symbol");
        require(chains[externalChainId].custody != address(0), "MB: chain missing");
        AssetInfo assetInfo = assets[externalToken][externalChainId];
        require(assetInfo.externalToken == externalToken, "MB: asset not found");
        assetInfo.externalName = externalName;
        assetInfo.externalSymbol = externalSymbol;
        emit AssetUpdated(assetInfo.enabled, externalChainId, assetInfo.externalDecimals, externalName, externalSymbol, externalToken, assetInfo.maxPerWithdrawal, assetInfo.stratoToken);
    }

    /**
     * @dev Sets token withdrawal limits for an existing asset
     * @notice Only the owner can set withdrawal limits for existing assets
     * @notice Allows configuring maximum withdrawal amounts for risk management
     * @notice Setting maxPerWithdrawal to 0 means unlimited withdrawals
     * @notice Validates that the asset exists before updating limits
     * @param externalChainId The external chain identifier where the asset is configured
     * @param externalToken The external token address to update limits for
     * @param maxPerWithdrawal Maximum amount per withdrawal (0 = unlimited)
     */
    function setWithdrawalLimits(
        uint256 externalChainId, address externalToken, uint256 maxPerWithdrawal
    ) external onlyOwner {
        require(externalChainId > 0, "MB: invalid chain id");
        require(chains[externalChainId].custody != address(0), "MB: chain missing");
        AssetInfo assetInfo = assets[externalToken][externalChainId];
        require(assetInfo.externalToken == externalToken, "MB: asset not found");
        assetInfo.maxPerWithdrawal = maxPerWithdrawal;
        emit AssetUpdated(assetInfo.enabled, externalChainId, assetInfo.externalDecimals, assetInfo.externalName, assetInfo.externalSymbol, externalToken, maxPerWithdrawal, assetInfo.stratoToken);
    }

    /**
     * @dev Sets chain configuration for bridge operations
     * @notice Configures external chain parameters including custody and router addresses
     * @param chainName The human-readable name of the external chain
     * @param custody The custody contract address on the external chain
     * @param enabled Whether the chain is enabled for bridge operations
     * @param externalChainId The unique identifier for the external chain
     * @param lastProcessedBlock The last processed block number for this chain
     * @param router The router contract address for deposits
     */
    function setChain(
        string chainName, address custody, bool enabled, uint256 externalChainId, uint256 lastProcessedBlock, address router
    ) external onlyOwner {
        require(chainName.length > 0, "MB: invalid chain name");
        require(custody != address(0), "MB: zero custody address");
        require(externalChainId > 0, "MB: invalid external chain id");
        require(router != address(0), "MB: zero router address");
        chains[externalChainId] = ChainInfo(chainName, custody, router, enabled, lastProcessedBlock);
        emit ChainUpdated(chainName, custody, enabled, externalChainId, lastProcessedBlock, router);
    }

    /**
     * @dev Updates the last processed block for a specific chain
     * @notice Prevents rollback attacks by ensuring block numbers only increase
     * @param externalChainId The external chain identifier
     * @param lastProcessedBlock The new last processed block number
     */
    function setLastProcessedBlock(
        uint256 externalChainId, uint256 lastProcessedBlock
    ) external onlyOwner {
        require(externalChainId > 0, "MB: invalid external chain id");
        ChainInfo chainInfo = chains[externalChainId];
        require(chainInfo.custody != address(0), "MB: chain missing");

        require(lastProcessedBlock >= chainInfo.lastProcessedBlock, "MB: cannot rollback block");

        chainInfo.lastProcessedBlock = lastProcessedBlock;
        emit LastProcessedBlockUpdated(externalChainId, lastProcessedBlock);
    }

    /**
     * @dev Sets pause states for deposits and withdrawals
     * @notice Circuit breaker functionality to pause bridge operations
     * @param _deposits Whether to pause deposit operations
     * @param _withdrawals Whether to pause withdrawal operations
     */
    function setPause(bool _deposits, bool _withdrawals) external onlyOwner {
        depositsPaused    = _deposits;
        withdrawalsPaused = _withdrawals;
        emit PauseToggled(_deposits, _withdrawals);
    }

    /**
     * @dev Sets the token factory address
     * @notice Only the owner can update the token factory address
     * @param newFactory The new token factory address (must not be zero address)
     */
    function setTokenFactory(address newFactory) external onlyOwner {
        require(newFactory != address(0), "MB: zero");
        emit TokenFactoryUpdated(newFactory, tokenFactory);
        tokenFactory = newFactory;
    }

    /**
     * @dev Sets the USDST token address
     * @notice Only the owner can update the USDST address
     * @param newUSDSTAddress The new USDST token address (must not be zero address)
     */
    function setUSDSTAddress(address newUSDSTAddress) external onlyOwner {
        require(newUSDSTAddress != address(0), "MB: zero USDST address");
        emit USDSTAddressUpdated(newUSDSTAddress, USDST_ADDRESS);
        USDST_ADDRESS = newUSDSTAddress;
    }

    /**
     * @dev Toggles the enabled state of a chain
     * @notice Only the owner can enable/disable chains
     * @param externalChainId The external chain identifier
     * @param enabled Whether to enable or disable the chain
     */
    function toggleChain(uint256 externalChainId, bool enabled) external onlyOwner {
        require(externalChainId > 0, "MB: invalid chain id");
        require(chains[externalChainId].custody != address(0), "MB: chain not found");

        chains[externalChainId].enabled = enabled;
        emit ChainToggled(enabled, externalChainId);
    }

    /**
     * @dev Toggles the enabled state of an asset
     * @notice Only the owner can enable/disable assets
     * @param externalToken The external token address
     * @param externalChainId The external chain identifier
     * @param enabled Whether to enable or disable the asset
     */
    function toggleAsset(address externalToken, uint256 externalChainId, bool enabled) external onlyOwner {
        require(externalChainId > 0, "MB: invalid chain id");
        require(assets[externalToken][externalChainId].externalChainId == externalChainId, "MB: asset not found");

        assets[externalToken][externalChainId].enabled = enabled;
        emit AssetToggled(enabled, externalChainId, externalToken);
    }

    // ───────────── Escrow related functions ─────────────
    /**
     * @dev Burns tokens from the escrow contract
     * @param token The token contract address
     * @param amount The amount of tokens to burn
     * @return actualAmount The actual amount of tokens burned
     */
    function _burnFunds(address token, uint256 amount) internal returns (uint256 actualAmount) {
        uint256 balanceBefore = IERC20(token).balanceOf(address(this));
        Token(token).burn(address(this), amount);
        actualAmount = balanceBefore - IERC20(token).balanceOf(address(this));
        require(actualAmount > 0, "MB: no tokens burned");
    }

    /**
     * @dev Escrows tokens from a user to this contract
     * @param token The token contract address
     * @param from The address to transfer tokens from
     * @param amount The amount of tokens to escrow
     * @return actualAmount The actual amount of tokens escrowed
     */
    function _escrowFunds(address token, address from, uint256 amount) internal returns (uint256 actualAmount) {
        uint256 balanceBefore = IERC20(token).balanceOf(address(this));
        require(IERC20(token).transferFrom(from, address(this), amount), "MB: transfer failed");
        actualAmount = IERC20(token).balanceOf(address(this)) - balanceBefore;
        require(actualAmount > 0, "MB: no tokens received");
    }

    /**
     * @dev Mints tokens to a recipient address
     * @param token The token contract address
     * @param to The address to mint tokens to
     * @param amount The amount of tokens to mint
     * @return actualAmount The actual amount of tokens minted
     */
    function _mintFunds(address token, address to, uint256 amount) internal returns (uint256 actualAmount) {
        uint256 balanceBefore = IERC20(token).balanceOf(to);
        Token(token).mint(to, amount);
        actualAmount = IERC20(token).balanceOf(to) - balanceBefore;
        require(actualAmount > 0, "MB: no tokens minted");
    }

    /**
     * @dev Refunds tokens from this contract to a recipient
     * @param token The token contract address
     * @param to The address to refund tokens to
     * @param amount The amount of tokens to refund
     * @return actualAmount The actual amount of tokens refunded
     */
    function _refundFunds(address token, address to, uint256 amount) internal returns (uint256 actualAmount) {
        uint256 balanceBefore = IERC20(token).balanceOf(address(this));
        require(IERC20(token).transfer(to, amount), "MB: transfer failed");
        actualAmount = balanceBefore - IERC20(token).balanceOf(address(this));
        require(actualAmount > 0, "MB: no tokens sent");
    }

    // ───────────── Deposit & withdrawal related functions ─────────────
    // ───────────── Deposit flow functions ─────────────
    /**
     * @dev Records a deposit transaction from an external chain
     * @notice Step-1 of the deposit flow - observes external transaction
     * @notice Creates deposit record but does NOT mint tokens yet
     * @notice Allows off-chain confirmation windows and fraud checks before step-2
     * @notice Converts external token amounts to STRATO token amounts using decimal conversion
     * @param externalChainId The external chain identifier where the deposit occurred
     * @param externalSender The address that sent the transaction on the external chain
     * @param externalToken The token address on the external chain
     * @param externalTokenAmount The amount of external tokens to deposit (in external token decimals)
     * @param externalTxHash The transaction hash on the external chain
     * @param stratoRecipient The STRATO address to receive the minted tokens
     */
    function deposit(
        uint256 externalChainId, address externalSender, address externalToken, uint256 externalTokenAmount, string externalTxHash, address stratoRecipient
    ) public onlyOwner whenDepositsOpen {
        require(externalChainId > 0, "MB: invalid external chain id");
        require(externalSender != address(0), "MB: invalid external sender");
        require(externalTokenAmount > 0, "MB: invalid external token amount");
        require(externalTxHash.length > 0, "MB: invalid external tx hash");
        require(stratoRecipient != address(0), "MB: invalid strato recipient");
        require(chains[externalChainId].enabled, "MB: chain not enabled");

        // Normalize the transaction hash to prevent case-variation replay attacks
        // This is because SolidVm does not support bytes32
        string normalizedTxHash = externalTxHash.normalizeHex();
        require(deposits[externalChainId][normalizedTxHash].bridgeStatus == BridgeStatus.NONE, "MB: duplicate deposit");

        AssetInfo a = assets[externalToken][externalChainId];
        require(a.enabled, "MB: asset not enabled");
        require(TokenFactory(tokenFactory).isTokenActive(a.stratoToken), "MB: inactive token");

        // Example: 1e6 USDC * 10^(18-6) = 1e6 * 10^12 = 1e18 USDCST tokens
        uint256 stratoTokenAmount = externalTokenAmount * (10 ** (DECIMAL_PLACES - a.externalDecimals));
        require(stratoTokenAmount > 0, "MB: invalid strato token amount");

        deposits[externalChainId][normalizedTxHash] = DepositInfo(
            BridgeStatus.INITIATED, externalSender, externalToken, block.timestamp, stratoRecipient, a.stratoToken, stratoTokenAmount, block.timestamp
        );

        emit DepositInitiated(externalChainId, externalSender, normalizedTxHash, stratoRecipient, a.stratoToken, stratoTokenAmount);
    }

    /**
     * @dev Records multiple deposit transactions from external chains in a single call
     * @notice Batch version of deposit function for gas efficiency
     * @notice All arrays must have the same length and correspond by index
     * @notice Each deposit follows the same validation rules as individual deposit function
     * @notice Converts external token amounts to STRATO token amounts using decimal conversion
     * @param externalChainIds Array of external chain identifiers
     * @param externalSenders Array of external sender addresses
     * @param externalTokens Array of external token addresses
     * @param externalTokenAmounts Array of external token amounts (in external token decimals)
     * @param externalTxHashes Array of external transaction hashes
     * @param stratoRecipients Array of STRATO recipient addresses
     */
    function depositBatch(
        uint256[] externalChainIds, address[] externalSenders, address[] externalTokens, uint256[] externalTokenAmounts, string[] externalTxHashes, address[] stratoRecipients
    ) external onlyOwner whenDepositsOpen {
        uint256 n = externalChainIds.length;
        require(n > 0 && n == externalSenders.length && n == externalTokens.length && n == externalTokenAmounts.length && n == externalTxHashes.length && n == stratoRecipients.length, "MB: len");
        for (uint256 i = 0; i < n; i++) {
            deposit(externalChainIds[i], externalSenders[i], externalTokens[i], externalTokenAmounts[i], externalTxHashes[i], stratoRecipients[i]);
        }
    }

    /**
     * @dev Confirms a deposit and mints wrapped tokens
     * @notice Step-2.1 of the deposit flow - verification passed, mint wrapped tokens
     * @notice Only deposits in INITIATED or PENDING_REVIEW status can be confirmed
     * @notice Mints the corresponding STRATO tokens to the recipient
     * @param externalChainId The external chain identifier where the deposit occurred
     * @param externalTxHash The transaction hash on the external chain
     */
    function confirmDeposit(
        uint256 externalChainId, string externalTxHash
    ) public onlyOwner whenDepositsOpen {
        require(externalChainId > 0, "MB: invalid external chain id");
        require(chains[externalChainId].enabled, "MB: chain not enabled");
        require(externalTxHash.length > 0, "MB: invalid external tx hash");

        // Normalize the transaction hash to prevent case-variation replay attacks
        // This is because SolidVm does not support bytes32
        string normalizedTxHash = externalTxHash.normalizeHex();
        DepositInfo d = deposits[externalChainId][normalizedTxHash];
        require(d.bridgeStatus == BridgeStatus.INITIATED || d.bridgeStatus == BridgeStatus.PENDING_REVIEW, "MB: bad state");

        uint256 actualMintedAmount = _mintFunds(d.stratoToken, d.stratoRecipient, d.stratoTokenAmount);
        require(actualMintedAmount > 0, "MB: no tokens minted");

        d.bridgeStatus = BridgeStatus.COMPLETED;
        d.timestamp = block.timestamp;

        emit DepositCompleted(externalChainId, normalizedTxHash);
    }

    /**
     * @dev Confirms multiple deposits and mints wrapped tokens in a single call
     * @notice Batch version of confirmDeposit function for gas efficiency
     * @notice All arrays must have the same length and correspond by index
     * @notice Each deposit follows the same validation rules as individual confirmDeposit function
     * @param externalChainIds Array of external chain identifiers
     * @param externalTxHashes Array of external transaction hashes
     */
    function confirmDepositBatch(
        uint256[] externalChainIds, string[] externalTxHashes
    ) external onlyOwner whenDepositsOpen {   
        uint256 n = externalChainIds.length;
        require(n > 0 && n == externalTxHashes.length, "MB: len");
        for (uint256 i = 0; i < n; i++) {
            confirmDeposit(externalChainIds[i], externalTxHashes[i]);
        }
    }

    /**
     * @dev Sets a deposit for manual review when verification fails
     * @notice Step-2.2 of the deposit flow - verification failed, set deposit for manual review
     * @notice Only deposits in INITIATED status can be set for review
     * @notice Owner can later abort or manually confirm reviewed deposits
     * @param externalChainId The external chain identifier where the deposit occurred
     * @param externalTxHash The transaction hash on the external chain
     */
    function reviewDeposit(
        uint256 externalChainId, string externalTxHash
    ) public onlyOwner whenDepositsOpen {
        require(externalChainId > 0, "MB: invalid external chain id");
        require(chains[externalChainId].enabled, "MB: chain not enabled");
        require(externalTxHash.length > 0, "MB: invalid external tx hash");

        // Normalize the transaction hash to prevent case-variation replay attacks
        // This is because SolidVm does not support bytes32
        string normalizedTxHash = externalTxHash.normalizeHex();
        DepositInfo d = deposits[externalChainId][normalizedTxHash];
        require(d.bridgeStatus == BridgeStatus.INITIATED, "MB: bad state");

        d.bridgeStatus = BridgeStatus.PENDING_REVIEW;
        d.timestamp = block.timestamp;

        emit DepositPendingReview(externalChainId, normalizedTxHash);
    }

    /**
     * @dev Sets multiple deposits for manual review when verification fails
     * @notice Batch version of reviewDeposit function for gas efficiency
     * @notice All arrays must have the same length and correspond by index
     * @notice Each deposit follows the same validation rules as individual reviewDeposit function
     * @param externalChainIds Array of external chain identifiers
     * @param externalTxHashes Array of external transaction hashes
     */
    function reviewDepositBatch(
        uint256[] externalChainIds, string[] externalTxHashes
    ) external onlyOwner whenDepositsOpen {
        uint256 n = externalChainIds.length;
        require(n > 0 && n == externalTxHashes.length, "MB: len");

        for (uint256 i = 0; i < n; i++) {
            reviewDeposit(externalChainIds[i], externalTxHashes[i]);
        }
    }

    /**
     * @dev Aborts a deposit that was marked for manual review
     * @notice Step-2.3 of the deposit flow - cancel a deposit that was marked for review
     * @notice Only deposits in PENDING_REVIEW status can be aborted
     * @notice Only the owner can abort deposits, preventing token minting
     * @param externalChainId The external chain identifier where the deposit occurred
     * @param externalTxHash The transaction hash on the external chain
     */
    function abortDeposit(
        uint256 externalChainId, string externalTxHash
    ) public onlyOwner {
        require(externalChainId > 0, "MB: invalid external chain id");
        require(chains[externalChainId].enabled, "MB: chain not enabled");
        require(externalTxHash.length > 0, "MB: invalid external tx hash");

        // Normalize the transaction hash to prevent case-variation replay attacks
        // This is because SolidVm does not support bytes32
        string normalizedTxHash = externalTxHash.normalizeHex();
        DepositInfo d = deposits[externalChainId][normalizedTxHash];
        require(d.bridgeStatus == BridgeStatus.PENDING_REVIEW, "MB: bad state");

        d.bridgeStatus = BridgeStatus.ABORTED;
        d.timestamp = block.timestamp;

        emit DepositAborted(externalChainId, normalizedTxHash);
    }

    /**
     * @dev Aborts multiple deposits that were marked for manual review
     * @notice Batch version of abortDeposit function for gas efficiency
     * @notice All arrays must have the same length and correspond by index
     * @notice Each deposit follows the same validation rules as individual abortDeposit function
     * @param externalChainIds Array of external chain identifiers
     * @param externalTxHashes Array of external transaction hashes
     */
    function abortDepositBatch(
        uint256[] externalChainIds, string[] externalTxHashes
    ) external onlyOwner {
        uint256 n = externalChainIds.length;
        require(n > 0 && n == externalTxHashes.length, "MB: len");

        for (uint256 i = 0; i < n; i++) {
            abortDeposit(externalChainIds[i], externalTxHashes[i]);
        }
    }

    // ───────────── Withdrawal flow functions ─────────────
    /**
     * @dev Initiates a withdrawal request by escrowing tokens and creating a withdrawal record
     * @notice Step-1 of the withdrawal flow - user moves tokens into bridge escrow and creates request
     * @notice Returns deterministic withdrawal ID for indexers to enumerate without extra mappings
     * @notice Tokens are escrowed until the withdrawal is confirmed or aborted
     * @notice Converts STRATO token amounts to external token amounts using decimal conversion
     * @notice Any dust from decimal conversion rounding is kept by the user
     * @param externalChainId The external chain identifier where tokens should be sent
     * @param externalRecipient The address on the external chain to receive the tokens
     * @param externalToken The token address on the external chain
     * @param stratoTokenAmount The amount of STRATO tokens to withdraw (any dust from decimal conversion will be kept by user)
     * @return id The unique withdrawal identifier
     */
    function requestWithdrawal(
        uint256 externalChainId, address externalRecipient, address externalToken, uint256 stratoTokenAmount
    ) external whenWithdrawalsOpen returns (uint256 id) {
        require(externalChainId > 0, "MB: invalid external chain id");
        require(externalRecipient != address(0), "MB: invalid external recipient");
        require(stratoTokenAmount > 0, "MB: invalid strato token amount");
        require(chains[externalChainId].enabled, "MB: chain not enabled");

        AssetInfo a = assets[externalToken][externalChainId];
        require(a.enabled, "MB: asset not enabled");
        require(TokenFactory(tokenFactory).isTokenActive(a.stratoToken), "MB: inactive token");

        // Example: 1e18 USDCST tokens / 10^(18-6) = 1e18 / 10^12 = 1e6 USDC
        // Round down to the nearest integer
        uint256 externalTokenAmount = stratoTokenAmount / (10 ** (DECIMAL_PLACES - a.externalDecimals));
        require(externalTokenAmount > 0, "MB: not enough external tokens");

        stratoTokenAmount = externalTokenAmount * (10 ** (DECIMAL_PLACES - a.externalDecimals));
        require(a.maxPerWithdrawal == 0 || stratoTokenAmount <= a.maxPerWithdrawal, "MB: per-withdrawal cap");
        stratoTokenAmount = _escrowFunds(a.stratoToken, msg.sender, stratoTokenAmount);
        require(stratoTokenAmount > 0, "MB: no tokens escrowed");

        // Example: 1e18 USDCST tokens / 10^(18-6) = 1e18 / 10^12 = 1e6 USDC
        // Round down to the nearest integer
        externalTokenAmount = stratoTokenAmount / (10 ** (DECIMAL_PLACES - a.externalDecimals));
        require(externalTokenAmount > 0, "MB: invalid external token amount");

        id = ++withdrawalCounter;

        withdrawals[id] = WithdrawalInfo(
            BridgeStatus.INITIATED, "", externalChainId, externalRecipient, externalToken, externalTokenAmount, block.timestamp, msg.sender, a.stratoToken, stratoTokenAmount, block.timestamp
        );

        emit WithdrawalRequested(externalRecipient, externalChainId, externalTokenAmount, stratoTokenAmount, a.stratoToken, msg.sender, id);
    }

    /**
     * @dev Confirms a withdrawal request and sets it to pending review
     * @notice Step-2 of the withdrawal flow - custody transaction has been created but not executed
     * @notice Stores the custody transaction hash so UI can show approval progress
     * @notice Only withdrawals in INITIATED status can be confirmed
     * @param id The unique withdrawal identifier
     * @param custodyTxHash The custody transaction hash on the external chain
     */
    function confirmWithdrawal(
        uint256 id, string custodyTxHash
    ) public onlyOwner whenWithdrawalsOpen {
        require(id > 0, "MB: invalid withdrawal id");
        require(custodyTxHash.length > 0, "MB: invalid custody tx hash");

        WithdrawalInfo w = withdrawals[id];
        require(w.bridgeStatus == BridgeStatus.INITIATED, "MB: bad state");

        w.bridgeStatus = BridgeStatus.PENDING_REVIEW;
        w.timestamp = block.timestamp;

        // Normalize the custody tx hash to prevent case-variation replay attacks
        // This is because SolidVm does not support bytes32
        string normalizedCustodyTxHash = custodyTxHash.normalizeHex();
        w.custodyTxHash = normalizedCustodyTxHash;

        emit WithdrawalPending(normalizedCustodyTxHash, id);
    }

    /**
     * @dev Confirms multiple withdrawal requests and sets them to pending review
     * @notice Batch version of confirmWithdrawal function for gas efficiency
     * @notice All arrays must have the same length and correspond by index
     * @notice Each withdrawal follows the same validation rules as individual confirmWithdrawal function
     * @param ids Array of unique withdrawal identifiers
     * @param custodyTxHashes Array of custody transaction hashes on the external chain
     */
    function confirmWithdrawalBatch(
        uint256[] ids, string[] custodyTxHashes
    ) external onlyOwner whenWithdrawalsOpen {
        uint256 n = ids.length;
        require(n > 0 && n == custodyTxHashes.length, "MB: len");

        for (uint256 i = 0; i < n; i++) {
            confirmWithdrawal(ids[i], custodyTxHashes[i]);
        }
    }

    /**
     * @dev Finalizes a withdrawal by burning the escrowed tokens
     * @notice Step-3 of the withdrawal flow - custody transaction executed successfully, burn escrow
     * @notice Only withdrawals in PENDING_REVIEW status can be finalized
     * @notice Burns the corresponding STRATO tokens to complete the withdrawal
     * @param id The unique withdrawal identifier
     */
    function finaliseWithdrawal(
        uint256 id
    ) public onlyOwner whenWithdrawalsOpen {
        require(id > 0, "MB: invalid withdrawal id");

        WithdrawalInfo w = withdrawals[id];
        require(w.bridgeStatus == BridgeStatus.PENDING_REVIEW, "MB: bad state");

        uint256 actualBurnedAmount = _burnFunds(w.stratoToken, w.stratoTokenAmount);
        require(actualBurnedAmount > 0, "MB: no tokens burned");

        w.bridgeStatus = BridgeStatus.COMPLETED;
        w.timestamp = block.timestamp;

        emit WithdrawalCompleted(id);
    }

    /**
     * @dev Finalizes multiple withdrawals by burning the escrowed tokens
     * @notice Batch version of finaliseWithdrawal function for gas efficiency
     * @notice Each withdrawal follows the same validation rules as individual finaliseWithdrawal function
     * @param ids Array of unique withdrawal identifiers
     */
    function finaliseWithdrawalBatch(
        uint256[] ids
    ) external onlyOwner whenWithdrawalsOpen {
        uint256 n = ids.length;
        require(n > 0, "MB: len");

        for (uint256 i = 0; i < n; i++) {
            finaliseWithdrawal(ids[i]);
        }
    }

    /**
     * @dev Aborts a withdrawal and refunds the escrowed tokens
     * @notice Step-4 of the withdrawal flow - abort a withdrawal and refund tokens
     * @notice Admin can abort any withdrawal in INITIATED or PENDING_REVIEW status
     * @notice User can only abort their own withdrawal in INITIATED status after timeout
     * @notice Covers the scenario where admin disappears before confirming
     * @notice Does not cover the scenario where custody transaction is waiting to be signed
     * @param id The unique withdrawal identifier
     */
    function abortWithdrawal(
        uint256 id
    ) public {
        require(id > 0, "MB: invalid withdrawal id");

        WithdrawalInfo w = withdrawals[id];
        uint256 currentTimestamp = block.timestamp;

        AdminRegistry admin = AdminRegistry(owner());
        if (admin.whitelist(address(this), "abortWithdrawal", msg.sender)) {
            require(w.bridgeStatus == BridgeStatus.INITIATED || w.bridgeStatus == BridgeStatus.PENDING_REVIEW, "MB: not abortable");
        }
        else {
            require(msg.sender == w.stratoSender, "MB: not sender");
            require(w.bridgeStatus == BridgeStatus.INITIATED, "MB: not abortable");
            require(currentTimestamp >= w.requestedAt + WITHDRAWAL_ABORT_DELAY, "MB: wait 48h");
        }

        w.bridgeStatus = BridgeStatus.ABORTED;
        w.timestamp = currentTimestamp;

        uint256 actualRefundedAmount = _refundFunds(w.stratoToken, w.stratoSender, w.stratoTokenAmount);
        require(actualRefundedAmount > 0, "MB: no tokens refunded");

        emit WithdrawalAborted(id);
    }

    /**
     * @dev Aborts multiple withdrawals and refunds the escrowed tokens
     * @notice Batch version of abortWithdrawal function for gas efficiency
     * @notice Each withdrawal follows the same validation rules as individual abortWithdrawal function
     * @param ids Array of unique withdrawal identifiers
     */
    function abortWithdrawalBatch(
        uint256[] ids
    ) external {
        uint256 n = ids.length;
        require(n > 0, "MB: len");

        for (uint256 i = 0; i < n; i++) {
            abortWithdrawal(ids[i]);
        }
    }
}

// CDPEngine
// - Core CDP logic for multi-collateral USDST mint/burn
// - Accrues stability fee via rateAccumulator (RAY); all debt reads use scaledDebt * rate / RAY
// - Liquidation with direct seize (no auctions)
// - Fees: split between FeeCollector and CDPReserve (feeToReserveBps)
// - Pro-rata juniors: splits USDST from reserve across all active notes proportionally to their remaining caps
// - UPDATED: Per-asset minCR (minCR). User actions (borrow/withdraw) must keep CR ≥ minCR.
//            minCR is stored per asset in CollateralConfig and must be ≥ liquidationRatio.

import "./CDPVault.sol";
import "../Tokens/Token.sol";
import "../Tokens/TokenFactory.sol";
import "../Lending/PriceOracle.sol";
import "./CDPRegistry.sol";
import "../Admin/FeeCollector.sol";
import "./CDPReserve.sol";

import "../../abstract/ERC20/access/Ownable.sol";

contract record CDPEngine is Ownable {
    // Registry and shared components resolved from the registry
    CDPRegistry public registry;
    // Resolve Token, TokenFactory, and FeeCollector via registry at call time

    // Per‑asset configuration (see setCollateralAssetParams)
    struct CollateralConfig {
        uint liquidationRatio;          // WAD (e.g. 1.50e18)
        uint minCR;                     // WAD (e.g. 1.60e18) — action gate CR (must be ≥ liquidationRatio)
        uint liquidationPenaltyBps;     // 10000 = 100%
        uint closeFactorBps;            // 10000 = 100%
        uint stabilityFeeRate;          // per‑second factor (RAY)
        uint debtFloor;                 // minimum debt per vault (USD 1e18)
        uint debtCeiling;               // asset debt ceiling (USD 1e18)
        uint unitScale;                 // token units to 1e18 scale factor
        bool isPaused;                  // asset pause switch (all ops)
    }

    // Per‑asset global state
    struct CollateralGlobalState {
        uint rateAccumulator;   // RAY (>= RAY)
        uint lastAccrual;       // timestamp
        uint totalScaledDebt;   // sum of normalized principal (scaledDebt) across vaults
    }

    // Per‑vault state keyed by (user, asset)
    struct Vault {
        uint collateral;  // raw token units
        uint scaledDebt;  // index‑denominated debt
    }

    mapping(address => CollateralConfig) public record collateralConfigs;
    mapping(address => CollateralGlobalState) public record collateralGlobalStates;
    mapping(address => mapping(address => Vault)) public record vaults; // user => asset => vault

    bool public globalPaused;
    uint public RAY = 1e27;
    uint public WAD = 1e18;
    mapping(address => bool) public record isSupportedAsset;

    uint256 public feeToReserveBps; // portion of feeUSD sent to CDPReserve (0..10000)
    // uint public priceMaxAge = 1200;

    event FeeToReserveBpsSet(uint256 oldBps, uint256 newBps);
    event FeesRouted(address indexed asset, uint256 toReserve, uint256 toCollector);
    // event PriceMaxAgeSet(uint oldMaxAge, uint newMaxAge);

    // ─────────────── Events ───────────────
    event CollateralConfigured(
        address indexed asset,
        uint liquidationRatio,
        uint minCR,
        uint liquidationPenaltyBps,
        uint closeFactorBps,
        uint stabilityFeeRate,
        uint debtFloor,
        uint debtCeiling,
        uint unitScale,
        bool pause
    );

    event Accrued(
        address indexed asset,
        uint oldRate,
        uint newRate,
        uint deltaTime,
        uint totalScaledDebt
    );

    event Deposited(address indexed owner, address indexed asset, uint amount);
    event Withdrawn(address indexed owner, address indexed asset, uint amount);

    event USDSTMinted(
        address indexed owner,
        address indexed asset,
        uint amountUSD,
        uint totalScaledDebt,
        uint rateAccumulator
    );

    event USDSTBurned(
        address indexed owner,
        address indexed asset,
        uint amountUSD,
        uint totalScaledDebt,
        uint rateAccumulator
    );

    event LiquidationExecuted(
        address indexed borrower,
        address indexed asset,
        uint debtBurnedUSD,
        uint penaltyUSD,
        uint collateralOut,
        address indexed liquidator,
        uint remainingDebtUSD,
        uint rateAccumulator
    );
    event Paused(address indexed asset, bool isPaused);
    event PausedGlobal(bool isPaused);
    event JuniorParamsSet(uint premiumBps, uint sliceBps);

    event VaultUpdated(
        address indexed user,
        address indexed asset,
        uint collateral,
        uint scaledDebt
    );

    event RegistryUpdated(address indexed oldRegistry, address indexed newRegistry);

    // ───────────────────────── Registry Access Helpers ──────────────────────
    function _cdpVault() internal view returns (CDPVault) { return registry.cdpVault(); }
    function _cdpPriceOracle() internal view returns (PriceOracle) { return registry.priceOracle(); }
    function _usdst() internal view returns (Token) { return Token(address(registry.usdst())); }
    function _tokenFactory() internal view returns (TokenFactory) { return TokenFactory(address(registry.tokenFactory())); }
    function _feeCollector() internal view returns (FeeCollector) { return FeeCollector(address(registry.feeCollector())); }
    function _cdpReserve() internal view returns (CDPReserve) { return registry.cdpReserve(); }

    // ─────────────────────────── Access Modifiers ───────────────────────────
    modifier whenNotPaused(address asset) {
        require(!globalPaused, "CDPEngine: global pause");
        require(!collateralConfigs[asset].isPaused, "CDPEngine: asset paused");
        _;
    }

    modifier onlyKnownAsset(address asset) { 
        require(isSupportedAsset[asset], "unsupported"); _; 
    }

    modifier onlyActiveAsset(address asset) {
        require(isSupportedAsset[asset], "unsupported");
        require(_tokenFactory().isTokenActive(asset), "inactive");
        _;
    }

    // ─────────────────────────────── Constructor ─────────────────────────────
    constructor(address initialOwner) Ownable(initialOwner) { }

    function initialize(address _registry) external onlyOwner {
        // @dev important: must be set here for proxied instances; ensure consistency with desired initial values
        RAY = 1e27;
        WAD = 1e18;
        // priceMaxAge = 1200;

        require(_registry != address(0), "CDPEngine: invalid registry");
        registry = CDPRegistry(_registry);
    }

    /**
     * @notice Update registry reference and resync dependent addresses
     * @dev Must be called after wiring the registry to ensure cached references are set
     */
    function setRegistry(address _registry) external onlyOwner {
        require(_registry != address(0), "CDPEngine: invalid registry");
        address old = address(registry);
        registry = CDPRegistry(_registry);
        emit RegistryUpdated(old, _registry);
    }

    function setFeeToReserveBps(uint256 newBps) external onlyOwner {
        require(newBps <= 10000, "fee bps > 10000");
        uint256 old = feeToReserveBps;
        feeToReserveBps = newBps;
        emit FeeToReserveBpsSet(old, newBps);
    }

    // function setPriceMaxAge(uint newMaxAge) external onlyOwner {
    //     uint old = priceMaxAge;
    //     priceMaxAge = newMaxAge;
    //     emit PriceMaxAgeSet(old, newMaxAge);
    // }

    /**
     * @notice Internal helper to route fees between Reserve and FeeCollector
     * @dev Mints USDST fees and splits according to feeToReserveBps
     * @param asset The collateral asset (for event logging)
     * @param feeUSD The total fee amount to route
     */
    function _routeFees(address asset, uint256 feeUSD) internal {
        if (feeUSD > 0) {
            // Simple two-way split: Reserve vs FeeCollector
            uint256 toReserve   = (feeUSD * feeToReserveBps) / 10000;
            uint256 toCollector = feeUSD - toReserve;

            if (toReserve > 0) Token(_usdst()).mint(address(_cdpReserve()), toReserve);
            if (toCollector > 0) Token(_usdst()).mint(address(_feeCollector()), toCollector);

            emit FeesRouted(asset, toReserve, toCollector);
        }
    }

    // ───────────────────────────── User Actions ──────────────────────────────
    /**
     * @notice Deposit collateral from msg.sender into their vault
     * @dev Pulls tokens via transferFrom into CDPVault custody; emits Deposited and VaultUpdated
     */
    function deposit(address asset, uint amount) external onlyActiveAsset(asset) {
        require(amount > 0, "CDPEngine: Invalid amount");
        // Move collateral into vault custody and update in-memory vault balance
        _cdpVault().deposit(msg.sender, asset, amount);
        vaults[msg.sender][asset].collateral += amount;
        emit Deposited(msg.sender, asset, amount);
        emit VaultUpdated(msg.sender, asset, vaults[msg.sender][asset].collateral, vaults[msg.sender][asset].scaledDebt);
    }

    /**
     * @notice Withdraw explicit amount of collateral; requires CR ≥ minCR when debt > 0
     * @dev Accrues first; reverts if resulting CR would fall below threshold
     */
    function withdraw(address asset, uint amount) external onlyKnownAsset(asset) whenNotPaused(asset) {
        require(amount > 0, "CDPEngine: Invalid amount");
        Vault storage vault = vaults[msg.sender][asset];
        require(vault.collateral >= amount, "CDPEngine: Insufficient collateral");
        // Always accrue before reading debt/CR sensitive values
        _accrue(asset);
        // Optimistically reduce collateral, then validate CR if debt remains
        vault.collateral -= amount;
        if (vault.scaledDebt > 0) {
            uint crAfter = collateralizationRatio(msg.sender, asset);
            require(crAfter >= collateralConfigs[asset].minCR, "CDPEngine: below min CR");
        }
        // Perform custody move after checks
        _cdpVault().withdraw(msg.sender, asset, amount);
        emit Withdrawn(msg.sender, asset, amount);
        emit VaultUpdated(msg.sender, asset, vault.collateral, vault.scaledDebt);
    }

    /**
     * @notice Withdraw maximum safe collateral while preserving CR ≥ minCR
     * @dev Applies a +1 wei buffer when there is outstanding debt to avoid edge rounding
     * @return maxAmount The amount withdrawn
     */
    function withdrawMax(address asset) external onlyKnownAsset(asset) whenNotPaused(asset) returns (uint maxAmount) {
        // Accrue to get an up-to-date rateAccumulator before computing debt
        _accrue(asset);
        Vault storage vault = vaults[msg.sender][asset];
        uint debt = (vault.scaledDebt * collateralGlobalStates[asset].rateAccumulator) / RAY;
        if (debt == 0) {
            // No debt: user can withdraw all collateral
            maxAmount = vault.collateral;
        } else {
            // Compute collateral required to keep CR >= minCR
            (uint price, uint timestamp) = _cdpPriceOracle().getAssetPriceWithTimestamp(asset);
            require(price > 0, "invalid price");
            // require(block.timestamp - timestamp <= priceMaxAge, "CDPEngine: stale price");
            CollateralConfig memory config = collateralConfigs[asset];
            uint requiredCollateralValue = (debt * config.minCR) / WAD;
            uint requiredCollateral = (requiredCollateralValue * config.unitScale) / price;
            // Enforce a 1 wei buffer when debt exists to protect against rounding
            if (vault.collateral <= requiredCollateral + 1) {
                maxAmount = 0; // exactly at buffer or below => nothing withdrawable
            } else {
                maxAmount = vault.collateral - requiredCollateral - 1;
            }
        }
        if (maxAmount > 0) {
            // Update vault balance then move funds from custody
            vault.collateral -= maxAmount;
            _cdpVault().withdraw(msg.sender, asset, maxAmount);
            emit Withdrawn(msg.sender, asset, maxAmount);
            emit VaultUpdated(msg.sender, asset, vault.collateral, vault.scaledDebt);
        }
    }

    /**
     * @notice Mint a specific amount of USDST against collateral
     * @dev Checks debtCeiling and debtFloor, accrues first, and updates scaled debt and books
     *      Enforces CR ≥ minCR after mint
     */
    function mint(address asset, uint amountUSD) external whenNotPaused(asset) onlyActiveAsset(asset) {
        // Accrue fees so debt math uses the latest rateAccumulator
        _accrue(asset);
        require(amountUSD > 0, "CDPEngine: zero amount");
        // Load config/state and caller's vault
        CollateralConfig memory assetConfig = collateralConfigs[asset];
        CollateralGlobalState storage assetState = collateralGlobalStates[asset];
        Vault storage userVault = vaults[msg.sender][asset];
        // Compute current debt in USD using scaledDebt and rateAccumulator
        uint currentDebt = (userVault.scaledDebt * assetState.rateAccumulator) / RAY;
        // Value collateral in USD and compute borrow headroom from minCR
        (uint price, uint timestamp) = _cdpPriceOracle().getAssetPriceWithTimestamp(asset);
        require(price > 0, "invalid price");
        // require(block.timestamp - timestamp <= priceMaxAge, "CDPEngine: stale price");
        uint collateralValueUSD_calc = (userVault.collateral * price) / assetConfig.unitScale;
        uint maxBorrowableUSD = (collateralValueUSD_calc * WAD) / assetConfig.minCR;
        require(currentDebt + amountUSD < maxBorrowableUSD, "CDPEngine: insufficient collateral");
        // Enforce per-asset debt ceiling vs current outstanding debt (Maker-style)
        if (assetConfig.debtCeiling > 0) {
            uint assetDebtUSD = (assetState.totalScaledDebt * assetState.rateAccumulator) / RAY;
            require(assetDebtUSD + amountUSD <= assetConfig.debtCeiling, "CDPEngine: debt ceiling exceeded");
        }       
        // Increase scaled debt (principal) using current index
        uint scaledAdd = (amountUSD * RAY + assetState.rateAccumulator - 1) / assetState.rateAccumulator;
        userVault.scaledDebt += scaledAdd;
        assetState.totalScaledDebt += scaledAdd;
        // Enforce per-vault debt floor post-mint
        uint totalDebtAfter = (userVault.scaledDebt * assetState.rateAccumulator) / RAY;
        if (assetConfig.debtFloor > 0) {
            require(totalDebtAfter >= assetConfig.debtFloor, "CDPEngine: below debt floor");
        }
        // Mint USDST to the user; fees will be realized on repay
        Token(_usdst()).mint(msg.sender, amountUSD);
        emit USDSTMinted(msg.sender, asset, amountUSD, assetState.totalScaledDebt, assetState.rateAccumulator);
        emit VaultUpdated(msg.sender, asset, userVault.collateral, userVault.scaledDebt);
    }

    /**
     * @notice Mint the maximum safe USDST amount (applies 1-wei buffer)
     * @dev Computes headroom from CR and minCR, enforces ceiling/floor, and mints to user
     */
    function mintMax(address asset) external whenNotPaused(asset) onlyActiveAsset(asset) returns (uint amountMinted) {
        // Accrue to make the index current
        _accrue(asset);
        CollateralConfig memory config = collateralConfigs[asset];
        CollateralGlobalState storage assetState = collateralGlobalStates[asset];
        Vault storage userVault = vaults[msg.sender][asset];
        // Current owed in USD
        uint currentDebt = (userVault.scaledDebt * assetState.rateAccumulator) / RAY;
        // Compute borrow headroom from collateral value and minCR
        (uint price, uint timestamp) = _cdpPriceOracle().getAssetPriceWithTimestamp(asset);
        require(price > 0, "invalid price");
        // require(block.timestamp - timestamp <= priceMaxAge, "CDPEngine: stale price");
        uint collateralValueUSD_calc = (userVault.collateral * price) / config.unitScale;
        uint maxBorrowableUSD = (collateralValueUSD_calc * WAD) / config.minCR;
        require(maxBorrowableUSD > currentDebt, "No borrowing power");
        uint available = maxBorrowableUSD - currentDebt;
        // Apply 1 wei buffer to avoid rounding into liquidation edge
        amountMinted = available > 1 ? (available - 1) : 0; // 1-wei safety buffer
        require(amountMinted > 0, "No borrowing power");
        // Enforce per-asset ceiling vs current outstanding debt
        if (config.debtCeiling > 0) {
            uint assetDebtUSD = (assetState.totalScaledDebt * assetState.rateAccumulator) / RAY;
            require(assetDebtUSD + amountMinted <= config.debtCeiling, "CDPEngine: debt ceiling exceeded");
        }
        // Increase scaled principal at current index
        uint scaledAdd = (amountMinted * RAY + assetState.rateAccumulator - 1) / assetState.rateAccumulator;
        userVault.scaledDebt += scaledAdd;
        assetState.totalScaledDebt += scaledAdd;
        // Enforce per-vault floor after mint
        uint totalDebtAfter = (userVault.scaledDebt * assetState.rateAccumulator) / RAY;
        if (config.debtFloor > 0) {
            require(totalDebtAfter >= config.debtFloor, "CDPEngine: below debt floor");
        }
        // Mint funds to the user
        Token(_usdst()).mint(msg.sender, amountMinted);
        emit USDSTMinted(msg.sender, asset, amountMinted, assetState.totalScaledDebt, assetState.rateAccumulator);
        emit VaultUpdated(msg.sender, asset, userVault.collateral, userVault.scaledDebt);
    }

    function repay(address asset, uint amountUSD) external onlyKnownAsset(asset) {
        _accrue(asset);
        require(amountUSD > 0, "CDPEngine: zero amount");

        CollateralConfig memory config = collateralConfigs[asset];
        CollateralGlobalState storage assetState = collateralGlobalStates[asset];
        Vault storage userVault = vaults[msg.sender][asset];

        uint owed = (userVault.scaledDebt * assetState.rateAccumulator) / RAY;
        require(owed > 0, "CDPEngine: no debt");

        // Convert request to normalized delta
        uint repayAmount = amountUSD > owed ? owed : amountUSD;
        uint scaledDelta = (repayAmount * RAY) / assetState.rateAccumulator;
        if (scaledDelta > userVault.scaledDebt) scaledDelta = userVault.scaledDebt;

        // Preview post-repay debt for floor check
        uint newScaledDebt = userVault.scaledDebt - scaledDelta;
        uint owedAfterPreview = (newScaledDebt * assetState.rateAccumulator) / RAY;
        if (owedAfterPreview > 1 && config.debtFloor > 0 && owedAfterPreview < config.debtFloor) {
            revert("CDPEngine: repay leaves debt below floor; use repayAll");
        }

        // Exact extinguished USD at current index
        uint owedForDelta = (scaledDelta * assetState.rateAccumulator) / RAY;
        uint baseUSD = scaledDelta;
        uint feeUSD  = owedForDelta > baseUSD ? (owedForDelta - baseUSD) : 0;

        Token(_usdst()).burn(msg.sender, owedForDelta);

        // Route fees between Reserve and FeeCollector
        _routeFees(asset, feeUSD);

        userVault.scaledDebt = newScaledDebt;
        assetState.totalScaledDebt -= scaledDelta;

        // Dust cleanup (≤ 1 wei of USD debt)
        if (owedAfterPreview <= 1) {
            if (userVault.scaledDebt > 0) {
                assetState.totalScaledDebt -= userVault.scaledDebt;
                userVault.scaledDebt = 0;
            }
        }

        emit USDSTBurned(msg.sender, asset, owedForDelta, assetState.totalScaledDebt, assetState.rateAccumulator);
        emit VaultUpdated(msg.sender, asset, userVault.collateral, userVault.scaledDebt);
    }

    /**
     * @notice Repay all USDST debt and clear rounding by setting scaledDebt to zero
     * @dev Burns full owed (principal + fee), mints fee to collector, and zeroes principal book
     */
    function repayAll(address asset) external onlyKnownAsset(asset) {
        // Accrue to settle fees and compute exact owed at current index
        _accrue(asset);
        CollateralGlobalState storage assetState = collateralGlobalStates[asset];
        Vault storage userVault = vaults[msg.sender][asset];
        require(userVault.scaledDebt > 0, "CDPEngine: no debt");
        // Total owed in USD includes both principal and stability fee
        uint owed = (userVault.scaledDebt * assetState.rateAccumulator) / RAY;
        uint scaledDebtToRemove = userVault.scaledDebt;
        // Burn user's USDST equal to owed
        Token(_usdst()).burn(msg.sender, owed);
        // Split owed into base principal and fee components
        uint baseUSD = scaledDebtToRemove; // normalized principal (scaled units)
        uint feeUSD = owed > baseUSD ? (owed - baseUSD) : 0;

        // Route fees between Reserve and FeeCollector
        _routeFees(asset, feeUSD);

        userVault.scaledDebt = 0;
        assetState.totalScaledDebt -= scaledDebtToRemove;

        emit USDSTBurned(msg.sender, asset, owed, assetState.totalScaledDebt, assetState.rateAccumulator);
        emit VaultUpdated(msg.sender, asset, userVault.collateral, userVault.scaledDebt);
    }

    /**
    * @notice Liquidate an undercollateralized vault for a given collateral asset
    * @dev Steps:
    *      - Accrue, assert unhealthy (CR < LR)
    *      - Cap repay by totalDebt, closeFactor, and coverage INCLUDING penalty
    *      - Burn EXACT debt extinguished (handles rounding)
    *      - Mint fee to FeeCollector; reduce scaled principal/books
    *      - Seize collateral equal to (repay + penalty) at oracle price
    *      - Emit events and dust-clean if remainder <= 1 wei
    * @param collateralAsset Address of the collateral token
    * @param borrower Address of the vault owner being liquidated
    * @param debtToCover Desired repay amount in wei (18 decimals)
    */
    function liquidate(
        address collateralAsset,
        address borrower,
        uint debtToCover
    ) external onlyKnownAsset(collateralAsset) whenNotPaused(collateralAsset) {
        require(borrower != address(0) && borrower != msg.sender, "CDPEngine: invalid borrower");
        require(debtToCover > 0, "CDPEngine: zero debt amount");

        _accrue(collateralAsset);

        CollateralConfig memory config = collateralConfigs[collateralAsset];
        CollateralGlobalState storage assetState = collateralGlobalStates[collateralAsset];
        Vault storage borrowerVault = vaults[borrower][collateralAsset];
        require(borrowerVault.scaledDebt > 0, "CDPEngine: no debt to liquidate");

        uint borrowerCR = collateralizationRatio(borrower, collateralAsset);
        require(borrowerCR < config.liquidationRatio, "CDPEngine: position healthy");

        // Prices & caps
        (uint priceCollWei, uint timestamp) = _cdpPriceOracle().getAssetPriceWithTimestamp(collateralAsset);
        require(priceCollWei > 0, "CDPEngine: invalid collateral price");
        // require(block.timestamp - timestamp <= priceMaxAge, "CDPEngine: stale price");

        uint totalDebtWei   = (borrowerVault.scaledDebt * assetState.rateAccumulator) / RAY;
        uint closeFactorCap = (totalDebtWei * config.closeFactorBps) / 10000;

        uint collateralWei = (borrowerVault.collateral * priceCollWei) / config.unitScale;
        // Ensure repay + penalty can be paid fully in collateral:
        // repay <= collateralWei * 10000 / (10000 + penaltyBps)
        uint coverageCap = (collateralWei * 10000) / (10000 + config.liquidationPenaltyBps);

        // Repay amount capped by all constraints
        bool capBinds = false;
        uint repay = debtToCover;
        if (repay > totalDebtWei)   repay = totalDebtWei;
        if (repay > closeFactorCap) repay = closeFactorCap;
        if (repay >= coverageCap) { repay = coverageCap; capBinds = true; }
        require(repay > 0, "CDPEngine: nothing to liquidate");

        uint collateralToSeize = 0;
        uint penaltyWei = 0;

        // Convert to scaled and clamp to vault's scaledDebt
        uint scaledDebtToLiquidate = (repay * RAY) / assetState.rateAccumulator;
        if (scaledDebtToLiquidate > borrowerVault.scaledDebt) {
            scaledDebtToLiquidate = borrowerVault.scaledDebt;
        }
        uint owedForDelta = (scaledDebtToLiquidate * assetState.rateAccumulator) / RAY;

        // burn exact, route only interest
        Token(_usdst()).burn(msg.sender, owedForDelta);

        uint feeWei = owedForDelta > scaledDebtToLiquidate ? (owedForDelta - scaledDebtToLiquidate) : 0;
        if (feeWei > 0) _routeFees(collateralAsset, feeWei);

        borrowerVault.scaledDebt   -= scaledDebtToLiquidate;
        assetState.totalScaledDebt -= scaledDebtToLiquidate;

        if (capBinds) {
            collateralToSeize = borrowerVault.collateral;
            uint collateralUSD = (collateralToSeize * priceCollWei) / config.unitScale;
            penaltyWei = collateralUSD > owedForDelta ? (collateralUSD - owedForDelta) : 0;
        } else {
            penaltyWei = (owedForDelta * config.liquidationPenaltyBps) / 10000;
            uint debtWithPenaltyWei = owedForDelta + penaltyWei;
            collateralToSeize = (debtWithPenaltyWei * config.unitScale) / priceCollWei;
            if (collateralToSeize > borrowerVault.collateral) {
                collateralToSeize = borrowerVault.collateral;
            }
        }

        borrowerVault.collateral -= collateralToSeize;
        _cdpVault().seize(borrower, collateralAsset, msg.sender, collateralToSeize);

        uint finalDebtWei = (borrowerVault.scaledDebt * assetState.rateAccumulator) / RAY;

        if (borrowerVault.collateral == 0) {
            uint rem = (borrowerVault.scaledDebt * assetState.rateAccumulator) / RAY;
            if (rem > 1) {
                assetState.totalScaledDebt -= borrowerVault.scaledDebt;
                borrowerVault.scaledDebt = 0;
                badDebtUSDST[collateralAsset] += rem;
                emit BadDebtRealized(collateralAsset, borrower, rem);
            }
        }

        emit LiquidationExecuted(
            borrower,
            collateralAsset,
            owedForDelta,          
            penaltyWei,
            collateralToSeize,
            msg.sender,
            finalDebtWei,
            assetState.rateAccumulator
        );

        emit VaultUpdated(borrower, collateralAsset, borrowerVault.collateral, borrowerVault.scaledDebt);
    }

    // ───────────────────────── Accrual & Views ──────────────────────────────
    /**
     * @notice Accrue stability fees for an asset by advancing the rateAccumulator
     * @dev Uses discrete compounding: newRate = oldRate * rpow(stabilityFeeRate, dt, RAY) / RAY
     */
    function _accrue(address asset) internal {
        // Load config/state for the collateral asset
        CollateralConfig memory assetConfig = collateralConfigs[asset];
        CollateralGlobalState storage assetState = collateralGlobalStates[asset];
        if (assetState.lastAccrual == 0) {
            assetState.lastAccrual = block.timestamp;
            assetState.rateAccumulator = RAY;
            return;
        }
        uint dt = block.timestamp - assetState.lastAccrual; if (dt == 0) return;
        uint oldRate = assetState.rateAccumulator;
        // Compute per-period factor via fixed-point exponentiation (RAY scale)
        uint factor = _rpow(assetConfig.stabilityFeeRate, dt, RAY);
        // Advance accumulator, ensuring monotonicity (never below RAY)
        uint newRate = (oldRate * factor) / RAY; if (newRate < RAY) { newRate = RAY; }
        // Persist state and emit observability event
        assetState.rateAccumulator = newRate; assetState.lastAccrual = block.timestamp;
        emit Accrued(asset, oldRate, assetState.rateAccumulator, dt, assetState.totalScaledDebt);
    }

    /**
     * @notice Configure per-asset risk parameters
     * @dev Validates bounds for LR, minCR, penalty, close-factor, rate, floor/ceiling, and unitScale
     */
    function setCollateralAssetParams(
        address asset,
        uint liquidationRatio,
        uint minCR,
        uint liquidationPenaltyBps,
        uint closeFactorBps,
        uint stabilityFeeRate,
        uint debtFloor,
        uint debtCeiling,
        uint unitScale,
        bool pause
    ) public onlyOwner {
        require(asset != address(0), "CDPEngine: invalid asset");
        require(liquidationRatio >= WAD, "CDPEngine: LR too low");
        require(minCR >= liquidationRatio, "CDPEngine: minCR < LR");
        require(liquidationPenaltyBps >= 500 && liquidationPenaltyBps <= 3000, "penalty out of range");
        require(closeFactorBps >= 5000 && closeFactorBps <= 10000, "CDPEngine: close factor out of range");
        require(stabilityFeeRate >= RAY, "CDPEngine: stability fee too low");
        require(unitScale > 0, "CDPEngine: invalid unit scale");
        if (debtCeiling > 0) { require(debtFloor <= debtCeiling, "CDPEngine: debt floor above ceiling"); }

        CollateralConfig storage config = collateralConfigs[asset];
        config.liquidationRatio = liquidationRatio;
        config.minCR = minCR;
        config.liquidationPenaltyBps = liquidationPenaltyBps; 
        config.closeFactorBps = closeFactorBps; 
        config.stabilityFeeRate = stabilityFeeRate; 
        config.debtFloor = debtFloor; 
        config.debtCeiling = debtCeiling; 
        config.unitScale = unitScale;
        config.isPaused = pause;

        if (!isSupportedAsset[asset]) { isSupportedAsset[asset] = true; }

        emit CollateralConfigured(
            asset,
            liquidationRatio,
            minCR,
            liquidationPenaltyBps,
            closeFactorBps,
            stabilityFeeRate,
            debtFloor,
            debtCeiling,
            unitScale,
            pause
        );
    }

    /**
     * @notice Batch configure multiple collateral assets in one transaction
     * @dev All arrays must have equal non-zero length N; i-th entries map to the same asset
     */
    function setCollateralAssetParamsBatch(
        address[] calldata assets,
        uint[] calldata liquidationRatios,
        uint[] calldata minCRs,
        uint[] calldata liquidationPenaltyBpsArr,
        uint[] calldata closeFactorBpsArr,
        uint[] calldata stabilityFeeRates,
        uint[] calldata debtFloors,
        uint[] calldata debtCeilings,
        uint[] calldata unitScales,
        bool[] calldata pauses
    ) external onlyOwner {
        uint len = assets.length;
        require(len > 0, "CDPEngine: empty batch");
        require(
            liquidationRatios.length == len &&
            minCRs.length == len &&
            liquidationPenaltyBpsArr.length == len &&
            closeFactorBpsArr.length == len &&
            stabilityFeeRates.length == len &&
            debtFloors.length == len &&
            debtCeilings.length == len &&
            unitScales.length == len &&
            pauses.length == len,
            "CDPEngine: array length mismatch"
        );
        for (uint i = 0; i < len; i++) {
            setCollateralAssetParams(
                assets[i],
                liquidationRatios[i],
                minCRs[i],
                liquidationPenaltyBpsArr[i],
                closeFactorBpsArr[i],
                stabilityFeeRates[i],
                debtFloors[i],
                debtCeilings[i],
                unitScales[i],
                pauses[i]
            );
        }
    }

    /** Owner-only: pause/unpause a specific asset */
    function setPaused(address asset, bool isPaused) external onlyOwner {
        require(isSupportedAsset[asset], "CDPEngine: unsupported asset");
        collateralConfigs[asset].isPaused = isPaused;
        emit Paused(asset, isPaused);
    }

    /** Owner-only: pause/unpause the entire CDP engine */
    function setPausedGlobal(bool isPaused) external onlyOwner {
        globalPaused = isPaused;
        emit PausedGlobal(isPaused);
    }

    /**
     * @dev Fixed-point exponentiation (Maker-style), rounding half up.
     * @param x Base in RAY
     * @param n Exponent (uint)
     * @param base Radix (RAY = 1e27)
     * @return z Result in RAY
     */
    function _rpow(uint x, uint n, uint base) internal pure returns (uint z) {
        if (x == 0) return n == 0 ? base : 0;
        z = (n % 2 == 0) ? base : x;
        uint half = base / 2;
        for (n /= 2; n > 0; n /= 2) {
            uint xx = x * x;
            x = (xx + half) / base; // round
            if (n % 2 == 1) {
                uint zx = z * x;
                z = (zx + half) / base; // round
            }
        }
        return z;
    }

    /**
    * @notice Compute the user's collateralization ratio for a given asset (WAD scale; 1e18 = 1.0).
    * @dev CR = collateralUSD / debtUSD
    *      collateralUSD = (vault.collateral * price) / unitScale
    *      debtUSD      = (vault.scaledDebt * rateAccumulator) / RAY
    *      Returns type(uint).max when debt is zero (interpreted as infinite CR).
    * @param user  Vault owner address.
    * @param asset Collateral asset address.
    * @return crWad Collateralization ratio in WAD units.
    */



    function collateralizationRatio(address user, address asset) public view returns (uint crWad) {
        CollateralGlobalState storage s = collateralGlobalStates[asset];
        Vault storage v = vaults[user][asset];
        uint debtUSD = (v.scaledDebt * s.rateAccumulator) / RAY;
        if (debtUSD == 0) return (2**256 - 1); 
        (uint price, uint timestamp) = _cdpPriceOracle().getAssetPriceWithTimestamp(asset);
        require(price > 0, "invalid price");
        // require(block.timestamp - timestamp <= priceMaxAge, "CDPEngine: stale price");
        uint unitScale = collateralConfigs[asset].unitScale;
        uint collateralUSD = unitScale == 0 ? 0 : (v.collateral * price) / unitScale;
        return (collateralUSD * WAD) / debtUSD;
    }





    // ═══════════════════════════════════════════════════════════════════════════════════════════════════
    // ═══════════════════════════════════ BAD DEBT & JUNIOR SYSTEM ═══════════════════════════════════════
    // ═══════════════════════════════════════════════════════════════════════════════════════════════════





    // ─────────────── Bad Debt State ───────────────

    mapping(address => uint) public record badDebtUSDST; // 1e18, bad debt (per-asset), non-accruing
    uint256 public juniorPremiumBps;   // e.g., 1000 = +10% payout premium over principal burned

    // ─── Pro-rata juniors via global index fed by Reserve inflows ───
    // juniorIndex is RAY (1e27) and means: cumulative USD distributed per 1 USD of outstanding cap.
    uint256 public juniorIndex;                   // init lazily to 1e27
    uint256 public totalJuniorOutstandingUSDST;   // sum of all capUSDST
    uint256 private prevReserveBalance;          // last Reserve balance accounted into index

    struct JuniorNote {
        address owner;
        uint256 capUSDST;     // remaining cap in wei (decreases on claims)
        uint256 entryIndex;   // earning baseline (resets on claims)
    }

    mapping(address => JuniorNote) public record juniorNotes;


    // ─────────────── Bad Debt Events ───────────────

    event BadDebtRealized(address indexed asset, address indexed borrower, uint amountUSDST);
    event BadDebtRepaid(address indexed asset, uint amountUSDST, uint badDebtRemaining);
    event JuniorNoteCreated(address indexed owner, uint256 capUSDST);
    event JuniorNoteClosed(address indexed owner);
    event JuniorNoteClaimed(address indexed owner, uint256 paidUSDST, uint256 remainingUSDST);
    /// @notice Emitted whenever new Reserve inflows are indexed into juniorIndex.
    /// @dev progressWad is the per-sync fraction toward cap (x) in 1e18 (WAD) units.
    ///      Sum progressWad across a time window (and divide by 1e18) to get S for that window.
    event JuniorIndexSynced(
        uint256 deltaUSDST,         // USDST newly observed in Reserve for this sync
        uint256 outstandingUSDST,   // totalJuniorOutstandingUSDST used for this sync
        uint256 deltaIndexRay,      // index bump in RAY (1e27)
        uint256 progressWad,        // x in WAD (1e18): deltaIndexRay / 1e9
        uint256 newJuniorIndexRay,  // juniorIndex after the bump
        uint256 timestamp           // block.timestamp at sync
    );


    // ─────────────── Admin Functions ───────────────

    /// @notice Set the premium percentage for junior notes
    function setJuniorPremium(uint256 newPremiumBps) external onlyOwner {
        require(newPremiumBps <= 10000, "junior: premium > 100%");
        juniorPremiumBps = newPremiumBps;
        emit JuniorParamsSet(newPremiumBps, 0);
    }


    // ─────────────── Bad Debt & Junior Functions ───────────────

    /// @notice Index sync from Reserve inflows (O(1), no loops)
    /// @dev Emits per-sync progress so off-chain can sum to S over a window.
    function _syncReserveToIndex() internal {
        if (juniorIndex == 0) juniorIndex = 1e27;

        address reserveAddr = address(registry.cdpReserve());
        uint256 reserveBal = _usdst().balanceOf(reserveAddr);

        // Nothing new to index
        if (reserveBal <= prevReserveBalance) return;

        uint256 deltaUSDST = reserveBal - prevReserveBalance;
        if (deltaUSDST == 0) {
            prevReserveBalance = reserveBal; // keep accounting consistent
            return;
        }

        uint256 outstanding = totalJuniorOutstandingUSDST;

        // No juniors outstanding: just advance accounting baseline
        if (outstanding == 0) {
            prevReserveBalance = reserveBal;
            return;
        }

        // Convert USDST inflow into an index bump (RAY scale)
        uint256 deltaIndex = (deltaUSDST * RAY) / outstanding;  // RAY
        uint256 newIndex = juniorIndex + deltaIndex;

        // Per-$cap progress fraction x, in WAD (so you can sum to S easily)
        // x = deltaIndex / RAY  => WAD = deltaIndex / (RAY/WAD)
        uint256 progressWad = deltaIndex / (RAY / WAD); // == deltaIndex / 1e9

        // State updates
        juniorIndex = newIndex;
        prevReserveBalance = reserveBal;

        emit JuniorIndexSynced(
            deltaUSDST,
            outstanding,
            deltaIndex,
            progressWad,
            newIndex,
            block.timestamp
        );
    }

    /**
     * @notice Burns USDST to reduce bad debt for an asset, creating a junior note with premium
     * @param asset The asset whose bad debt will be reduced.
     * @param amountUSDST Desired USDST to burn in wei (will be clamped to remaining bad debt).
     * @return burnedUSDST  The actual USDST burned in wei.
     * @return capUSDST     The note's payout cap in wei (principal+premium).
     */
    function openJuniorNote(address asset, uint256 amountUSDST)
        external
        onlyKnownAsset(asset)
        returns (uint256 burnedUSDST, uint256 capUSDST)
    {
        require(amountUSDST > 0, "junior: zero amount");

        uint256 bad = badDebtUSDST[asset];
        require(bad > 0, "junior: no bad debt for asset");

        // Burn and reduce bad debt
        burnedUSDST = amountUSDST > bad ? bad : amountUSDST;
        Token(_usdst()).burn(msg.sender, burnedUSDST);
        badDebtUSDST[asset] = bad - burnedUSDST;
        emit BadDebtRepaid(asset, burnedUSDST, badDebtUSDST[asset]);

        // Cap with premium
        capUSDST = (burnedUSDST * (10000 + juniorPremiumBps)) / 10000;

        // 1) Pull new Reserve inflows into the index first
        _syncReserveToIndex();
        if (juniorIndex == 0) juniorIndex = 1e27;

        // 2) Handle existing note or create new one
        JuniorNote storage note = juniorNotes[msg.sender];
        if (note.owner == address(0)) {
            // Create new note
            juniorNotes[msg.sender] = JuniorNote(msg.sender, capUSDST, juniorIndex);
            totalJuniorOutstandingUSDST += capUSDST;
            emit JuniorNoteCreated(msg.sender, capUSDST);
        } else {
            // Merge new contribution with existing note using blended entry index
            uint256 oldCap = note.capUSDST;
            uint256 oldEntry = note.entryIndex;
            uint256 newCap = oldCap + capUSDST;

            // Blended entry = currentIndex - (oldCap/newCap) * (currentIndex - oldEntry)
            uint256 blendedEntry = juniorIndex;
            if (juniorIndex > oldEntry) {
                uint256 indexGrowth = juniorIndex - oldEntry;
                uint256 adjustment = (oldCap * indexGrowth) / newCap;
                blendedEntry = juniorIndex - adjustment;
            }

            note.capUSDST = newCap;
            note.entryIndex = blendedEntry;
            totalJuniorOutstandingUSDST += capUSDST;

            emit JuniorNoteCreated(msg.sender, newCap);
        }
    }

    /// @notice Calculate entitlement for a note at given index
    function _entitlement(JuniorNote storage note, uint256 idx) internal view returns (uint256) {
        if (note.owner == address(0)) return 0;
        if (note.capUSDST == 0) return 0;
        if (idx == 0) idx = 1e27;

        uint256 last = note.entryIndex;
        if (idx <= last) return 0;

        // Simple: remaining cap earns from its entry point
        uint256 ent = (note.capUSDST * (idx - last)) / 1e27;  // RAY → USDST wei
        if (ent > note.capUSDST) ent = note.capUSDST;  // Cap at remaining cap
        return ent;
    }


    /// @notice View function to show what's claimable for an owner
    function claimable(address owner) public view returns (uint256) {
        JuniorNote storage note = juniorNotes[owner];

        // Calculate effective index including unaccounted reserve inflows
        uint256 effectiveIndex = juniorIndex == 0 ? 1e27 : juniorIndex;
        address reserveAddr = address(registry.cdpReserve());
        uint256 reserveBalance = _usdst().balanceOf(reserveAddr);

        if (reserveBalance > prevReserveBalance && totalJuniorOutstandingUSDST > 0) {
            uint256 newInflows = reserveBalance - prevReserveBalance;
            uint256 indexBump = (newInflows * 1e27) / totalJuniorOutstandingUSDST;
            effectiveIndex += indexBump;
        }

        return _entitlement(note, effectiveIndex);
    }

    function claimJunior() external {
        require(!globalPaused, "CDPEngine: global pause");
        _syncReserveToIndex();
        JuniorNote storage note = juniorNotes[msg.sender];
        require(note.owner != address(0), "junior: no note");

        uint256 currentIndex = juniorIndex;
        uint256 currentCap = note.capUSDST;

        uint256 entitlement = _entitlement(note, currentIndex);
        require(entitlement > 0, "junior: nothing to claim");

        address reserveAddr = address(registry.cdpReserve());
        uint256 reserveBalance = _usdst().balanceOf(reserveAddr);
        require(reserveBalance > 0, "junior: reserve empty");

        uint256 payAmount = entitlement <= reserveBalance ? entitlement : reserveBalance;
        uint256 unpaidAmount = entitlement - payAmount;
        uint256 newCap = currentCap - payAmount;

        // --- Effects (before interaction) ---
        if (newCap == 0) {
            totalJuniorOutstandingUSDST -= payAmount;
            prevReserveBalance -= payAmount;
            delete juniorNotes[msg.sender].owner;
            delete juniorNotes[msg.sender].capUSDST;
            delete juniorNotes[msg.sender].entryIndex;
            emit JuniorNoteClaimed(msg.sender, payAmount, 0);
            emit JuniorNoteClosed(msg.sender);
        } else {
            // Adjust entry index to preserve unpaid entitlement
            uint256 indexAdjustment = (unpaidAmount == 0) ? 0 : (unpaidAmount * 1e27) / newCap;
            uint256 newEntryIndex = currentIndex - indexAdjustment;

            note.capUSDST = newCap;
            note.entryIndex = newEntryIndex;

            totalJuniorOutstandingUSDST -= payAmount;
            prevReserveBalance -= payAmount;

            emit JuniorNoteClaimed(msg.sender, payAmount, newCap);
        }

        // --- Interaction (after state updates) ---
        CDPReserve(address(registry.cdpReserve())).transferTo(msg.sender, payAmount);
    }

}

