/// @title SafetyModule (clean, 4626-lite)
/// @notice Holds USDST and issues sUSDST tokens via internal accounting.
///         - Rewards in USDST via notifyReward() raise price (exchangeRate).
///         - coverShortfall() transfers USDST to LendingPool and writes down system debt; price drops.
///         - Cooldown + unstake window enforce exit discipline.

contract record SafetyModule is Ownable {
    // ─── Events
    event Staked(address indexed user, uint assetsIn, uint sharesOut);
    event UnstakeCooldown(address indexed user, uint start, uint end);
    event Redeemed(address indexed user, uint sharesIn, uint assetsOut);
    event RewardNotified(uint amount);
    event ShortfallCovered(uint amount);
    event ParamsUpdated(uint cooldown, uint window, uint maxSlashBps);
    event TokensUpdated(address _asset, address _sToken);
    event TokenFactoryUpdated(address _tokenFactory);
    event EndpointsSynced(address _lendingPool, address _liquidityPool, address newAsset);
    event RegistryUpdated(address _lendingRegistry);

    // ─── Core
    LendingRegistry public lendingRegistry;
    LendingPool public  lendingPool;
    LiquidityPool public liquidityPool;
    TokenFactory public tokenFactory;
    address public  asset;   // USDST
    address public  sToken;  // sUSDST (ERC-20)

    // Cooldown mechanics
    uint public COOLDOWN_SECONDS = 259200;
    uint public UNSTAKE_WINDOW  = 172800;
    mapping(address => uint) public record cooldownStart; // 0 = not cooling

    // Policy
    uint public MAX_SLASH_BPS = 3000; // 30% per event

    // Internal asset tracking to prevent donation attacks
    uint256 private _managedAssets;

    constructor(address initialOwner) Ownable(initialOwner) { }

    function initialize(address _lendingRegistry, address _tokenFactory) external onlyOwner {
        // @dev important: must be set here for proxied instances; ensure consistency with desired initial values
        COOLDOWN_SECONDS = 259200;
        UNSTAKE_WINDOW = 172800;
        MAX_SLASH_BPS = 3000;

        require(_lendingRegistry != address(0)  && _tokenFactory != address(0), "SM:zero addr");
        lendingRegistry = LendingRegistry(_lendingRegistry);
        tokenFactory = TokenFactory(_tokenFactory);
    }

    modifier onlyActiveToken(address token) {
        require(token != address(0) && tokenFactory.isTokenActive(token), "Invalid or inactive token");
        _;
    }

    // ─────────────────────────────────────────
    // Registry syncing (admin)

    function setRegistry(address r) external onlyOwner {
        require(r != address(0), "SM:reg=0");
        lendingRegistry = LendingRegistry(r);
        emit RegistryUpdated(r);
    }

    function setTokenFactory(address _tokenFactory) external onlyOwner {
        require(_tokenFactory != address(0), "SM:reg=0");
        tokenFactory = TokenFactory(_tokenFactory);
        emit TokenFactoryUpdated(_tokenFactory);
    }

    /// @notice Pull latest values from registry and cache them.
    /// @dev Validates that LendingPool.borrowableAsset() matches cached (or initializes if first time).
    function syncFromRegistry() external onlyOwner {
        _syncFromRegistry();
    }

    /// @dev call this before setTokens()
    /// @dev call this after the LendingPool configuration, particularly `poolConfigurator.setBorrowableAsset(USDST)`
    function _syncFromRegistry() internal {
        address _lendingPool = lendingRegistry.getLendingPool();
        address _liquidityPool = lendingRegistry.getLiquidityPool();
        require(_lendingPool != address(0) && _liquidityPool != address(0), "SM:bad registry addrs");

        // Derive asset from LendingPool
        address newAsset = LendingPool(_lendingPool).borrowableAsset();
        require(newAsset != address(0), "SM:asset=0");

        // If already initialized, require asset to stay consistent
        if (address(asset) != address(0)) {
            require(newAsset == address(asset), "SM:asset mismatch");
        } else {
            asset = newAsset;
        }

        lendingPool   = LendingPool(_lendingPool);
        liquidityPool = LiquidityPool(_liquidityPool);

        emit EndpointsSynced(_lendingPool, _liquidityPool, newAsset);
    }


    // ─────────────────────────────────────────
    // Views / math
    // Vault TVL in underlying (uses internal tracking to prevent donation attacks)
    function totalAssets() public view returns (uint) 
    { 
        require(asset != address(0), "SM:asset not set");
        return _managedAssets; 
    }

    // Total shares outstanding (assumes sToken implements ERC20 totalSupply)
    function totalShares() public view returns (uint) 
    { 
        require(sToken != address(0), "SM:sToken not set");
        return IERC20(sToken).totalSupply(); 
    }

    /// @notice Current sUSDST price in USDST units (1e18 = 1.0).
    /// @dev
    ///  - Reverts if the module is not initialized (missing asset/sToken).
    ///  - If no shares exist yet, returns 1e18 (defines the initial price).
    ///  - Floors on division (rounds down), as with standard ERC-4626.
    /// @return rate Scaled 1e18 exchange rate = totalAssets / totalShares (or 1e18 when shares==0).
    function exchangeRate() public view returns (uint) {
        uint s = totalShares();
        if (s == 0) return 1e18;
        return (totalAssets() * 1e18) / s;
    }

    /// @notice Pure estimate of shares minted for depositing `assetsIn` right now.
    /// @dev
    ///  - Uses the CURRENT ratio only; ignores transfer fees and donation guard.
    ///  - If no shares exist yet, preview equals `assetsIn` (initial 1:1).
    ///  - Reverts if module is not initialized or `assetsIn == 0`.
    ///  - Actual mint uses balance-delta and may be LOWER when the token is fee-on-transfer.
    /// @param assetsIn Amount of USDST the user intends to stake.
    /// @return sharesOut Estimated shares that would be minted at the current ratio.
    function previewStake(uint assetsIn) external view returns (uint) {
        require(assetsIn > 0, "SM:zero");
        uint s = totalShares();
        uint a = totalAssets();
        if (s == 0) return assetsIn;           // initial 1:1
        require(a > 0, "SM:price=0");          // shares exist but vault has no assets 
        return (assetsIn * s) / a;             // floor by design
    }

    /// @notice Pure estimate of USDST returned for redeeming `sharesIn` right now.
    /// @dev
    ///  - Uses the CURRENT ratio only; ignores cooldown/window and caller’s balance.
    ///  - Reverts if module is not initialized, `sharesIn == 0`, or totalShares == 0.
    ///  - Floors on division (rounds down), matching actual redeem semantics.
    /// @param sharesIn Amount of sUSDST the user intends to redeem.
    /// @return assetsOut Estimated USDST that would be returned at the current ratio.
    function previewRedeem(uint sharesIn) external view returns (uint) {
        require(sharesIn > 0, "SM:zero");
        uint s = totalShares();
        require(s > 0, "SM:no shares"); 
        return (sharesIn * totalAssets()) / s;
    }

    // ─────────────────────────────────────────
    // User actions

    /// @notice Stake `assetsIn` USDST; mints shares using balance-delta to account for fee-on-transfer tokens.
    /// @dev Guards:
    ///  - Active underlying (prevents deposits into offboarded market)
    ///  - Donation guard on first mint (no pre-loaded funds)
    ///  - Slippage (minSharesOut)
    function stake(uint assetsIn, uint minSharesOut) external onlyActiveToken(asset) onlyActiveToken(sToken) returns (uint sharesOut) {
        require(assetsIn > 0, "SM:zero");
        uint s = totalShares();
        uint beforeBal = totalAssets();

        if (s == 0) {
            require(beforeBal == 0, "SM:init stray funds"); // donation guard
        } else {
            require(beforeBal > 0, "SM:price=0");  // prevent (s>0, a==0) 
        }

        uint256 bal = IERC20(asset).balanceOf(address(this));
        require(IERC20(asset).transferFrom(msg.sender, address(this), assetsIn), "SM: stake transfer failed");
        uint256 delta = IERC20(asset).balanceOf(address(this)) - bal;
        require(delta > 0, "SM:no delta");
        _managedAssets += delta;

        sharesOut = (s == 0) ? delta : (delta * s) / beforeBal;
        require(sharesOut > 0, "SM:dust");
        require(sharesOut >= minSharesOut, "SM:slippage");

        Token(sToken).mint(msg.sender, sharesOut);

        // Reset cooldown on new stake
        cooldownStart[msg.sender] = 0;

        emit Staked(msg.sender, delta, sharesOut);
    }

    /// @notice Start cooldown. After COOLDOWN_SECONDS elapse, you have UNSTAKE_WINDOW to redeem.
    /// @dev Overwrites previous starts.
    function startCooldown() external {
        uint start = block.timestamp;
        cooldownStart[msg.sender] = start;
        emit UnstakeCooldown(msg.sender, start, start + COOLDOWN_SECONDS);
    }

    /// @notice Redeem shares for USDST to `to` after cooldown and within unstake window.
    /// @dev Caller must hold the shares in wallet (withdraw from Chef first).
    function redeem(uint sharesIn, uint minAssetsOut) external returns (uint assetsOut) {
        require(sharesIn > 0, "SM:zero");
        require(IERC20(sToken).balanceOf(msg.sender) >= sharesIn, "SM:not holder");

        uint start = cooldownStart[msg.sender];
        require(start > 0, "SM:no cooldown");
        require(block.timestamp >= start + COOLDOWN_SECONDS, "SM:cooling");
        require(block.timestamp <= start + COOLDOWN_SECONDS + UNSTAKE_WINDOW, "SM:window over");

        uint a = totalAssets();
        uint s = totalShares();
        assetsOut = (sharesIn * a) / s;
        require(assetsOut > 0, "SM:dust");
        require(assetsOut >= minAssetsOut, "SM:slippage");

        // burn then transfer
        Token(sToken).burn(msg.sender, sharesIn);

        uint256 bal = IERC20(asset).balanceOf(address(this));
        require(IERC20(asset).transfer(msg.sender, assetsOut), "SM: redeem transfer failed");
        uint256 delta = bal - IERC20(asset).balanceOf(address(this));
        require(delta > 0, "SM:no delta");
        _managedAssets -= delta;

        if (IERC20(sToken).balanceOf(msg.sender) == 0) cooldownStart[msg.sender] = 0;

        emit Redeemed(msg.sender, sharesIn, delta);
    }

    // ─────────────────────────────────────────
    // Rewards / Shortfall
    // ─────────────────────────────────────────
    /// @notice Pull USDST from owner and treat as rewards (price ↑ for all holders).
    function notifyReward(uint amount) external onlyOwner {
        require(amount > 0, "SM:zero");

        uint256 bal = IERC20(asset).balanceOf(address(this));
        require(IERC20(asset).transferFrom(msg.sender, address(this), amount), "SM: notifyReward transfer failed");
        uint256 delta = IERC20(asset).balanceOf(address(this)) - bal;
        require(delta > 0, "SM:no delta");
        _managedAssets += delta;

        emit RewardNotified(delta);
    }

    /// @notice Slash vault to cover protocol shortfall.
    /// @dev Data plane: send USDST to LiquidityPool.
    /// Control plane: tell LendingPool to consume badDebt (accounting).

    function coverShortfall(uint256 amount) external onlyOwner returns (uint256 covered) {
        require(amount > 0, "SM:zero");

        // Live caps
        uint256 ta        = totalAssets();                         // SM TVL
        uint256 bd        = lendingPool.badDebt();                 // live bad debt in base units
        require(bd > 0, "SM:no bad debt");

        uint256 maxSlash  = (ta * MAX_SLASH_BPS) / 10000;

        // Compute the actual amount we are willing & able to cover
        uint256 covered = amount;
        if (covered > ta)        covered = ta;        // cannot send more than vault assets
        if (covered > maxSlash)  covered = maxSlash;  // per-event slash cap
        if (covered > bd)        covered = bd;        // don't overfund beyond bad debt

        require(covered > 0, "SM:nothing to cover");

        // Push exactly what will be consumed, then notify LendingPool
        uint256 bal = IERC20(asset).balanceOf(address(this));
        require(IERC20(asset).transfer(address(liquidityPool), covered), "SM: coverShortfall transfer failed");
        uint256 delta = bal - IERC20(asset).balanceOf(address(this));
        require(delta > 0, "SM:no delta");
        _managedAssets -= delta;

        lendingPool.coverShortfall(delta);

        emit ShortfallCovered(delta);
    }

    // ─────────────────────────────────────────
    // Admin

    /// @notice Update cooldown/window and per-event slash cap.
    function setParams(uint cooldown, uint window, uint maxSlashBps) external onlyOwner {
        require(cooldown > 0 && window > 0, "SM:bad params");
        require(maxSlashBps <= 10000, "SM:bad slash");
        COOLDOWN_SECONDS = cooldown;
        UNSTAKE_WINDOW = window;
        MAX_SLASH_BPS = maxSlashBps;
        emit ParamsUpdated(cooldown, window, maxSlashBps);
    }

    /// @notice set the tokens - typically one-time
    /// @dev call this after syncFromRegistry() so that lendingPool is set
    function setTokens(address _sToken, address _asset) external onlyOwner {
        require(_sToken != address(0), "Invalid sToken address");
        require(_asset != address(0), "Invalid underlyingAsset address");
        // Ensure SM protects the same asset as LendingPool
        require(LendingPool(address(lendingPool)).borrowableAsset() == _asset, "SM:asset mismatch");
        // Avoid accidental equality (receipt token must differ from underlying)
        require(_sToken != _asset, "SM:equal tokens");

        sToken = _sToken;
        asset = _asset;
        emit TokensUpdated(_asset, _sToken);
    }

    /// @notice Recover stray assets that were donated to the contract without affecting internal tracking.
    /// @dev This prevents donation attacks by removing surplus tokens without updating totalAssets().
    /// @param to Address to send the stray assets to (should be a safe recipient like liquidityPool).
    function recoverStrayAssets(address to) external onlyOwner {
        require(to != address(0), "SM:bad recipient");
        uint256 stray = IERC20(asset).balanceOf(address(this)) - totalAssets();
        require(stray > 0, "SM:no stray");
        require(IERC20(asset).transfer(to, stray), "SM:transfer failed");
    }

    /// @notice Rescue stray tokens (not the vault asset).
    function rescueToken(address token, address to, uint amount) external onlyOwner {
        require(token != address(asset), "SM:no USDST rescue");
        require(IERC20(token).transfer(to, amount), "SM: rescue transfer failed");
    }
}

// SPDX-License-Identifier: MIT
import "PoolFactory.sol";
import "../Tokens/Token.sol";
import "../Tokens/TokenFactory.sol";
import "../Admin/FeeCollector.sol";
import "../../abstract/ERC20/access/Ownable.sol";

/**
 * @title Pool
 * @notice A decentralized exchange (DEX) liquidity pool for trading between two ERC20 tokens
 * @dev This contract implements an automated market maker (AMM) with constant product formula
 * 
 * Key Features:
 * - Automated market making using x * y = k formula
 * - Liquidity provision and removal with LP token rewards
 * - Swap functionality with configurable fees
 * - Fee distribution between protocol and liquidity providers
 * - Reentrancy protection for security
 * 
 * Fee Structure:
 * - Total swap fee is split between protocol and LP providers
 * - Protocol fee goes to fee collector
 * - LP fee is distributed to liquidity providers based on their share
 * 
 * @author Mercata Protocol
 * @version 1.0.0
 */
contract record Pool is Ownable {

    // ============ EVENTS ============

    /// @notice Emitted when a swap occurs
    /// @param sender The address that initiated the swap
    /// @param tokenIn The address of the input token
    /// @param tokenOut The address of the output token
    /// @param amountIn The amount of input tokens
    /// @param amountOut The amount of output tokens received
    event Swap(address sender, address tokenIn, address tokenOut, uint256 amountIn, uint256 amountOut);

    /// @notice Emitted when liquidity is added to the pool
    /// @param provider The address that provided liquidity
    /// @param tokenBAmount The amount of tokenB added
    /// @param tokenAAmount The amount of tokenA added
    event AddLiquidity(address provider, uint256 tokenBAmount, uint256 tokenAAmount);

        /// @notice Emitted when liquidity is removed from the pool
    /// @param provider The address that removed liquidity
    /// @param tokenBAmount The amount of tokenB received
    /// @param tokenAAmount The amount of tokenA received
    event RemoveLiquidity(address provider, uint256 tokenBAmount, uint256 tokenAAmount);

    /// @notice Emitted when excess tokens are skimmed from the pool
    /// @param to The address that received the excess tokens
    /// @param tokenAAmount The amount of excess tokenA skimmed
    /// @param tokenBAmount The amount of excess tokenB skimmed
    event Skim(address to, uint256 tokenAAmount, uint256 tokenBAmount);

    /// @notice Emitted when the pool's reserves are synced with current balances
    /// @param tokenABalance The new balance of tokenA
    /// @param tokenBBalance The new balance of tokenB
    event Sync(uint256 tokenABalance, uint256 tokenBBalance);

    // ============ STATE VARIABLES ============

    /// @notice The pool factory who created this pool
    PoolFactory public poolFactory;

    /// @notice The first token in the trading pair
    Token public tokenA;

    /// @notice The second token in the trading pair
    Token public tokenB;

    /// @notice The liquidity provider token representing ownership in the pool
    Token public lpToken;

    /// @notice Reentrancy guard to prevent recursive calls
    bool private locked;   

    /// @notice Current exchange rate from tokenA to tokenB
    decimal public aToBRatio;

    /// @notice Current exchange rate from tokenB to tokenA
    decimal public bToARatio;

    /// @notice Current balance of tokenA in the pool
    uint public tokenABalance;

    /// @notice Current balance of tokenB in the pool
    uint public tokenBBalance;

    /// @notice Pool-specific swap fee rate in basis points (0 = use factory default)
    uint256 public swapFeeRate;

    /// @notice Pool-specific LP share percentage in basis points (0 = use factory default)
    uint256 public lpSharePercent;

    /// @notice Whether to charge swap fees on internal zap swaps (default: true)
    bool public zapSwapFeesEnabled = true;

    // ============ MODIFIERS ============

    /// @notice Prevents reentrant calls to functions
    /// @dev Uses a simple boolean lock to prevent recursive calls
    modifier nonReentrant() {
        require(!locked, "REENTRANT");
        locked = true;
        _;
        locked = false;
    }

    /// @notice Modifier to check if the caller is the pool factory
    modifier onlyPoolFactory() {
        require(
            msg.sender == address(poolFactory)
            || msg.sender == owner(), // admin override would be useful here - ariya
            "Caller is not PoolFactory");
        _;
    }

    // ============ INTERNAL FUNCTIONS ============

    /// @notice Get the fee collector address from the factory
    /// @return The address of the fee collector contract
    function _feeCollector() internal view returns (address) {
        return PoolFactory(poolFactory).feeCollector();
    }

    /// @notice Get the token factory address from the factory
    /// @return The address of the token factory contract
    function _tokenFactory() internal view returns (address) {
        return PoolFactory(poolFactory).tokenFactory();
    }

    /// @notice Get the effective swap fee rate for this pool
    /// @return The swap fee rate in basis points (uses pool-specific rate if set, otherwise factory default)
    function _swapFeeRate() internal view returns (uint256) {
        if (swapFeeRate == 0) {
            return PoolFactory(poolFactory).swapFeeRate();
        }
        return swapFeeRate;
    }

    /// @notice Get the effective LP share percentage for this pool
    /// @return The LP share percentage in basis points (uses pool-specific rate if set, otherwise factory default)
    function _lpSharePercent() internal view returns (uint256) {
        if (lpSharePercent == 0) {
            return PoolFactory(poolFactory).lpSharePercent();
        }
        return lpSharePercent;
    }

    // ============ CONSTRUCTOR ============

    constructor(address initialOwner) Ownable(initialOwner) {}

    /// @notice Initialize a new liquidity pool
    /// @param tokenAAddr The address of the first token in the pair
    /// @param tokenBAddr The address of the second token in the pair
    /// @param lpTokenAddr The address of the LP token contract
    /// @param _owner The address of the owner of the pool
    /// @dev Should be called by the PoolFactory contract
    function initialize(
        address tokenAAddr, 
        address tokenBAddr,
        address lpTokenAddr
    ) external onlyOwner {
        require(tokenAAddr != address(0), "Zero tokenA address");
        require(tokenBAddr != address(0), "Zero tokenB address");
        require(lpTokenAddr != address(0), "Zero lpToken address");

        // @dev important: must be set here for proxied instances;
        // ensure consistency with desired initial values
        zapSwapFeesEnabled = true;

        tokenA = Token(tokenAAddr);
        tokenB = Token(tokenBAddr);
        lpToken = Token(lpTokenAddr);

        poolFactory = PoolFactory(msg.sender);
    }

    // ============ UTILITY FUNCTIONS ============
    /// @notice Sync the pool's reserves with current balances (external version)
    /// @dev Updates reserves to match current token balances
    function sync() external onlyPoolFactory {
        tokenABalance = tokenA.balanceOf(address(this));
        tokenBBalance = tokenB.balanceOf(address(this));
        _updateRatios();
        emit Sync(tokenABalance, tokenBBalance);
    }

    /// @notice Force balances to match reserves
    /// @param to Address to send the excess tokens to
    function skim(address to) external onlyPoolFactory {
        require(to != address(0), "Invalid recipient");
        uint256 excessA = tokenA.balanceOf(address(this)) - tokenABalance;
        uint256 excessB = tokenB.balanceOf(address(this)) - tokenBBalance;

        if (excessA > 0) {
            require(tokenA.transfer(to, excessA), "TokenA skim failed");
        }
        if (excessB > 0) {
            require(tokenB.transfer(to, excessB), "TokenB skim failed");
        }

        emit Skim(to, excessA, excessB);
    }
    /// @notice Update the pool's ratios
    /// @dev Called after operations that change token balances
    function _updateRatios() internal {
        aToBRatio = _getCurrentTokenRatio(true);
        bToARatio = _getCurrentTokenRatio(false);
    }

    /// @notice Update the pool's state variables with new balances
    /// @param newTokenABalance The new tokenA balance
    /// @param newTokenBBalance The new tokenB balance
    function _updateStateVars(uint256 newTokenABalance, uint256 newTokenBBalance) internal {
        tokenABalance = newTokenABalance;
        tokenBBalance = newTokenBBalance;
        _updateRatios();
    }

    /// @notice Calculate the current exchange ratio between tokens
    /// @param isAToB If true, calculate A to B ratio; if false, calculate B to A ratio
    /// @return The exchange ratio as a decimal value
    /// @dev Returns 0 if either reserve is too small to calculate a meaningful ratio
    function _getCurrentTokenRatio(bool isAToB) internal view returns (decimal) {
        decimal tokenAReserve = decimal(tokenABalance);
        decimal tokenBReserve = decimal(tokenBBalance);

        if (tokenAReserve <= 0.000000000000000000 || tokenBReserve <= 0.000000000000000000) {
            return 0.000000000000000000;
        }

        if (isAToB) {
            return decimal((tokenBReserve * 1.000000000000000000) / tokenAReserve) / 1.000000000000000000;
        } else {
            return decimal((tokenAReserve * 1.000000000000000000) / tokenBReserve) / 1.000000000000000000;
        }
        return 0.000000000000000000;
    }

    // ============ CORE FUNCTIONS ============

    /// @notice Add liquidity to the pool and receive LP tokens
    /// @param tokenBAmount The amount of tokenB to add (used as the base for calculations)
    /// @param maxTokenAAmount The maximum amount of tokenA the user is willing to add
    /// @return The amount of LP tokens minted to the user
    /// @dev For the first liquidity provision, tokenBAmount determines the initial LP token supply
    /// @dev For subsequent provisions, the ratio must match the current pool ratio
    /// @dev The user must approve both tokens for transfer before calling this function
    function addLiquidity(
        uint256 tokenBAmount,
        uint256 maxTokenAAmount,
        uint256 deadline
    ) external returns (uint256) {
        require(tokenBAmount > 0 && maxTokenAAmount > 0, "Invalid inputs");
        require(block.timestamp <= deadline, "EXPIRED");

        uint256 totalLiquidity = lpToken.totalSupply();
        uint256 tokenAAmount;
        uint256 mintAmount;

        if (totalLiquidity > 0) {
            tokenAAmount = (tokenBAmount * tokenABalance / tokenBBalance) + 1;
            mintAmount = tokenBAmount * totalLiquidity / tokenBBalance;
            require(maxTokenAAmount >= tokenAAmount, "Insufficient tokenA amount");
        } else {
            tokenAAmount = maxTokenAAmount;
            mintAmount = tokenBAmount;
        }

        lpToken.mint(msg.sender, mintAmount);
        require(tokenB.transferFrom(msg.sender, address(this), tokenBAmount), "TokenB transfer failed");
        require(tokenA.transferFrom(msg.sender, address(this), tokenAAmount), "TokenA transfer failed");

        _updateStateVars(tokenABalance + tokenAAmount, tokenBBalance + tokenBAmount);
        emit AddLiquidity(msg.sender, tokenBAmount, tokenAAmount);
        return mintAmount;
    }

    /// @notice Remove liquidity from the pool by burning LP tokens
    /// @param lpTokenAmount The amount of LP tokens to burn
    /// @param minTokenBAmount The minimum amount of tokenB to receive
    /// @param minTokenAAmount The minimum amount of tokenA to receive
    /// @return tokenBAmount The amount of tokenB received
    /// @return tokenAAmount The amount of tokenA received
    /// @dev The user must approve LP tokens for burning before calling this function
    /// @dev Slippage protection is provided by minTokenBAmount and minTokenAAmount parameters
    function removeLiquidity(
        uint256 lpTokenAmount, 
        uint256 minTokenBAmount,
        uint256 minTokenAAmount,
        uint256 deadline
    ) external returns (uint256, uint256) {
        require(lpTokenAmount > 0 && minTokenBAmount > 0 && minTokenAAmount > 0, "Invalid inputs");
        require(block.timestamp <= deadline, "EXPIRED");
        uint256 totalLiquidity = lpToken.totalSupply();
        require(totalLiquidity > 0, "No liquidity");
        uint256 tokenAReserve = tokenABalance;
        uint256 tokenBReserve = tokenBBalance;
        uint256 tokenBAmount = lpTokenAmount * tokenBReserve / totalLiquidity;
        uint256 tokenAAmount = lpTokenAmount * tokenAReserve / totalLiquidity;

        require(tokenBAmount >= minTokenBAmount && tokenAAmount >= minTokenAAmount, "Insufficient amounts");

        require(tokenB.transfer(msg.sender, tokenBAmount), "TokenB transfer failed");
        require(tokenA.transfer(msg.sender, tokenAAmount), "TokenA transfer failed");

        lpToken.burn(msg.sender, lpTokenAmount);
        _updateStateVars(tokenABalance - tokenAAmount, tokenBBalance - tokenBAmount);
        emit RemoveLiquidity(msg.sender, tokenBAmount, tokenAAmount);

        return (tokenBAmount, tokenAAmount);
    }

    // ============ SWAP FUNCTIONS ============

    /// @notice Calculate the output amount for a given input amount using the constant product formula
    /// @param inputAmount The amount of input tokens
    /// @param inputReserve The current reserve of input tokens
    /// @param outputReserve The current reserve of output tokens
    /// @return The amount of output tokens that would be received
    /// @dev Uses the formula: outputAmount = (inputAmount * outputReserve) / (inputReserve + inputAmount)
    function getInputPrice(
        uint256 inputAmount,
        uint256 inputReserve,
        uint256 outputReserve
    ) pure returns (uint256) {
        require(inputReserve > 0 && outputReserve > 0, "Invalid reserves");
        uint256 numerator = inputAmount * outputReserve;
        uint256 denominator = inputReserve + inputAmount;
        return numerator / denominator;
    }

    /// @notice Swap tokens using the automated market maker
    /// @param isAToB If true, swap tokenA for tokenB; if false, swap tokenB for tokenA
    /// @param amountIn The amount of input tokens to swap
    /// @param minAmountOut The minimum amount of output tokens to receive (slippage protection)
    /// @return amountOut The actual amount of output tokens received
    /// @dev The user must approve input tokens for transfer before calling this function
    /// @dev Fees are automatically deducted and distributed between protocol and LP providers
    /// @dev Reentrancy protection is applied to prevent attacks
    function swap(
        bool isAToB,
        uint256 amountIn,
        uint256 minAmountOut,
        uint256 deadline
    ) external nonReentrant returns (uint256 amountOut) {
        require(amountIn > 0 && minAmountOut > 0, "Invalid input");
        require(block.timestamp <= deadline, "EXPIRED");

        Token inputToken = isAToB ? tokenA : tokenB;
        Token outputToken = isAToB ? tokenB : tokenA;

        uint256 inputReserve = isAToB ? tokenABalance : tokenBBalance;
        uint256 outputReserve = isAToB ? tokenBBalance : tokenABalance;

        uint256 fee = (amountIn * _swapFeeRate()) / 10000;
        uint256 lpFee = (fee * _lpSharePercent()) / 10000;
        uint256 protocolFee = fee - lpFee;

        uint256 netInput = amountIn - fee;

        // Transfer full amount to pool
        require(inputToken.transferFrom(msg.sender, address(this), amountIn), "Input transfer failed");

        // Send protocol fee to fee collector
        require(inputToken.transfer(_feeCollector(), protocolFee), "Protocol fee transfer failed");

        amountOut = getInputPrice(netInput, inputReserve, outputReserve);
        require(amountOut >= minAmountOut, "Slippage check failed");

        require(outputToken.transfer(msg.sender, amountOut), "Output xfer failed");

        // Update balances: net input stays in pool, output is sent out
        if (isAToB) {
            _updateStateVars(tokenABalance + netInput, tokenBBalance - amountOut);
        } else {
            _updateStateVars(tokenABalance - amountOut, tokenBBalance + netInput);
        }

        emit Swap(msg.sender, address(inputToken), address(outputToken), amountIn, amountOut);
    }

    /// @notice Transfer the pool to a new factory
    /// @param newFactory The address of the new factory
    /// @dev This function can only be called by the current PoolFactory contract
    function transferPoolToFactory(address newFactory) external onlyPoolFactory {
        require(newFactory != address(0), "Invalid factory address");
        poolFactory = PoolFactory(newFactory);
    }

    /// @notice Set fee parameters for this pool (factory only)
    /// @param newSwapFeeRate New swap fee rate in basis points (e.g., 30 = 0.3%)
    /// @param newLpSharePercent New LP share percentage in basis points (e.g., 7000 = 70%)
    /// @dev This function can only be called by the PoolFactory contract
    /// @dev Updates both swap fee rate and LP share percentage in a single transaction
    /// @dev If set to 0, the pool will use the factory's default values
    /// @dev Maximum swap fee rate is 10% (1000 basis points)
    /// @dev LP share percentage must be between 0 and 100% (0-10000 basis points)
    function setFeeParameters(
        uint256 newSwapFeeRate,
        uint256 newLpSharePercent
    ) external onlyPoolFactory {
        require(newSwapFeeRate > 0 && newSwapFeeRate <= 1000, "Invalid swap fee rate"); // Max 10%
        require(newLpSharePercent > 0 && newLpSharePercent <= 10000, "Invalid LP share percent"); // Max 100%

        swapFeeRate = newSwapFeeRate;
        lpSharePercent = newLpSharePercent;
    }

    /// @notice Toggle swap fees for internal zap swaps (owner only)
    /// @param enabled Whether to charge fees on internal zap swaps
    /// @dev When disabled, zap swaps are fee-free, improving capital efficiency for liquidity providers
    /// @dev When enabled, zap swaps follow the same fee structure as regular swaps
    function setZapSwapFeesEnabled(bool enabled) external onlyOwner {
        zapSwapFeesEnabled = enabled;
    }

    // ============ ZAP-IN (SINGLE TOKEN LIQUIDITY) ============
    /// @notice Calculate integer square root of a uint256 (Babylonian method)
    function _sqrt(uint256 y) internal pure returns (uint256 z) {
        if (y > 3) {
            z = y;
            uint256 x = y / 2 + 1;
            while (x < z) {
                z = x;
                x = (y / x + x) / 2;
            }
        } else if (y != 0) {
            z = 1;
        }
    }

    /// @notice Compute optimal swap amount for single-sided liquidity (generic fee)
    /// @dev Derived from Uniswap-V2 zap formula, generalized for fee in basis points.
    function _getOptimalSwapAmount(
        uint256 reserveIn,
        uint256 userIn,
        uint256 feeBps
    ) internal pure returns (uint256) {
        require(feeBps < 10000, "Fee too high");
        uint256 a = 10000 - feeBps; // effective multipler (e.g., 9970 for 0.3%)
        uint256 b = 10000;
        // term = sqrt( reserveIn * ( userIn * 4 * a * b + reserveIn * (a + b) ** 2 ) )
        uint256 term1 = userIn * 4 * a * b;
        uint256 term2 = reserveIn * (a + b) * (a + b);
        uint256 term = _sqrt(reserveIn * (term1 + term2));
        uint256 numerator = term - reserveIn * (a + b);
        return numerator / (2 * a);
    }

    function _internalSwapForZap(
        bool isAToB,
        uint256 amountIn
    ) internal returns (uint256 amountOut) {
        uint256 inputReserve = isAToB ? tokenABalance : tokenBBalance;
        uint256 outputReserve = isAToB ? tokenBBalance : tokenABalance;

        uint256 netInput;
        if (zapSwapFeesEnabled) {
            uint256 fee = (amountIn * _swapFeeRate()) / 10000;
            uint256 lpFee = (fee * _lpSharePercent()) / 10000;
            uint256 protocolFee = fee - lpFee;
            netInput = amountIn - fee;

            // protocol fee sent to collector
            Token inputToken = isAToB ? tokenA : tokenB;
            require(inputToken.transfer(_feeCollector(), protocolFee), "Fee transfer failed");
        } else {
            netInput = amountIn; // no fees charged
        }

        amountOut = getInputPrice(netInput, inputReserve, outputReserve);

        // Note: For internal zap swaps, we don't update balances here since all tokens
        // stay in the pool. The balance updates happen in the calling function.
    }

    function _mintLiquidityAfterZap(
        uint256 tokenBContribution,
        uint256 tokenAContribution
    ) internal returns (uint256 liquidityMinted) {
        uint256 totalLiquidity = lpToken.totalSupply();
        uint256 tokenBReserve = tokenBBalance;
        liquidityMinted = tokenBContribution * totalLiquidity / tokenBReserve;

        lpToken.mint(msg.sender, liquidityMinted);
        emit AddLiquidity(msg.sender, tokenBContribution, tokenAContribution);
    }

    /// @notice Add liquidity with a single token (zap-in)
    /// @param isAToB True if depositing tokenA only, false if depositing tokenB only
    /// @param amountIn Amount of the single token supplied by the user
    /// @param deadline Expiry timestamp
    /// @return liquidityMinted Amount of LP tokens minted to the user
    function addLiquiditySingleToken(
        bool isAToB,
        uint256 amountIn,
        uint256 deadline
    ) external returns (uint256 liquidityMinted) {
        require(amountIn > 0, "Invalid inputs");
        require(block.timestamp <= deadline, "EXPIRED");
        require(lpToken.totalSupply() > 0, "POOL_EMPTY");

        // Transfer full amount from user to pool
        Token depositToken = isAToB ? tokenA : tokenB;
        uint256 reserveIn = isAToB ? tokenABalance : tokenBBalance; // reserve before deposit
        require(depositToken.transferFrom(msg.sender, address(this), amountIn), "Deposit transfer failed");

        uint256 feeBps = zapSwapFeesEnabled ? _swapFeeRate() : 0;
        uint256 swapAmt = _getOptimalSwapAmount(reserveIn, amountIn, feeBps);

        uint256 amountOut = _internalSwapForZap(isAToB, swapAmt);

        uint256 tokenAContribution;
        uint256 tokenBContribution;
        if (isAToB) {
            tokenAContribution = amountIn - swapAmt;
            tokenBContribution = amountOut;
        } else {
            tokenBContribution = amountIn - swapAmt;
            tokenAContribution = amountOut;
        }

        liquidityMinted = _mintLiquidityAfterZap(tokenBContribution, tokenAContribution);
        _updateStateVars(tokenABalance + tokenAContribution, tokenBBalance + tokenBContribution);
    }
}

/**
 * @title PoolFactory
 * @notice Factory pattern contract that standardizes pool creation and tracking
 * @dev While pools are created here, users interact directly with pool contracts after creation
 *
 * The factory serves three main purposes:
 * 1. Standardized pool creation (owner only)
 * 2. Pool registry - lookup existing pools for tokenA pairs
 * 3. Pool tracking - maintain list of all created pools
 *
 * Similar to Uniswap's factory pattern:
 * - Use factory to find/create pools
 * - All trading/core functions happen directly with pool contracts
 */

import "Pool.sol";
import "../../abstract/ERC20/access/Ownable.sol";
import "../Proxy/Proxy.sol";
import "../Tokens/TokenFactory.sol";
import "../Tokens/Token.sol";

/// @notice Pool factory contract
contract record PoolFactory is Ownable {

    // ============ EVENTS ============

    /// @notice Event emitted when a new pool is created
    event NewPool(address tokenA, address tokenB, address pool);

    /// @notice Event emitted when pools are migrated
    event PoolsMigrated(address oldFactory, address newFactory, uint256 poolCount);

    /// @notice Event emitted when the admin registry is updated
    event AdminRegistryUpdated(address newRegistry);

    /// @notice Event emitted when the token factory is updated
    event TokenFactoryUpdated(address newFactory);

    /// @notice Event emitted when fee collectors are updated
    event FeeCollectorsUpdated(address newFeeCollector);

    /// @notice Event emitted when fee parameters are updated
    event FeeParametersUpdated(uint256 newSwapFeeRate, uint256 newLpSharePercent);

    /// @notice Event emitted when pool fee parameters are updated
    event PoolFeeParametersUpdated(address poolAddress, uint256 newSwapFeeRate, uint256 newLpSharePercent);

    // ============ STATE VARIABLES ============

    /// @notice Mapping of tokenA/tokenB pairs to pool addresses
    mapping(address => mapping(address => address)) public record pools;

    /// @notice Array of all pool addresses
    address[] public record allPools;

    /// @notice Admin registry contract address
    address public adminRegistry;

    /// @notice Token factory contract address
    address public tokenFactory;

    /// @notice Fee collector address
    address public feeCollector;

    /// @notice Swap fee rate in basis points (e.g., 30 = 0.3%)
    uint256 public swapFeeRate;

    /// @notice LP share percentage in basis points (e.g., 7000 = 70%)
    uint256 public lpSharePercent;

    // ============ CONSTRUCTOR ============

    /// @notice Constructor
    /// @param initialOwner The initial owner of the contract
    constructor(address initialOwner) Ownable(initialOwner) { }

    /// @notice Initialize the contract
    /// @param _tokenFactory The address of the token factory
    /// @param _adminRegistry The address of the admin registry
    /// @param _feeCollector The address of the fee collector
    function initialize(address _tokenFactory, address _adminRegistry, address _feeCollector) external onlyOwner {
        require(_adminRegistry != address(0), "Zero admin registry address");
        require(_tokenFactory  != address(0), "Zero token factory address");
        require(_feeCollector  != address(0), "Zero fee collector address");

        adminRegistry = _adminRegistry;
        tokenFactory = _tokenFactory;
        feeCollector = _feeCollector;
        swapFeeRate = 30;
        lpSharePercent = 7000;

        emit FeeParametersUpdated(swapFeeRate, lpSharePercent);
        emit FeeCollectorsUpdated(feeCollector);
        emit AdminRegistryUpdated(adminRegistry);
        emit TokenFactoryUpdated(tokenFactory);
    }

    // ============ MODIFIERS ============

    /// @notice Modifier to check if tokens are active
    /// @param tokenA First token address
    /// @param tokenB Second token address
    modifier tokensActive(address tokenA, address tokenB) {
        require(TokenFactory(tokenFactory).isTokenActive(tokenA) && TokenFactory(tokenFactory).isTokenActive(tokenB), "Token not active");
        _;
    }

    // ============ ADMIN FUNCTIONS ============

    /// @notice Update the admin registry address (owner only)
    function setAdminRegistry(address _adminRegistry) external onlyOwner {
        require(_adminRegistry != address(0), "Zero admin registry address");
        address oldRegistry = address(adminRegistry);
        adminRegistry = _adminRegistry;
        emit AdminRegistryUpdated(_adminRegistry);
    }

    /// @notice Update the token factory address (owner or admin)
    function setTokenFactory(address _tokenFactory) external onlyOwner {
        require(_tokenFactory != address(0), "Zero token factory address");
        address oldFactory = address(tokenFactory);
        tokenFactory = _tokenFactory;
        emit TokenFactoryUpdated(_tokenFactory);
    }

    /// @notice Update the fee collector address (owner or admin)
    /// @dev This updates the factory's fee collector - pools read from factory
    function setFeeCollector(address newFeeCollector) external onlyOwner {
        require(newFeeCollector != address(0), "Zero fee collector address");
        address oldFeeCollector = feeCollector;
        feeCollector = newFeeCollector;

        emit FeeCollectorsUpdated(newFeeCollector);
    }

    /// @notice Update fee parameters for the factory (owner or admin)
    /// @param newSwapFeeRate New swap fee rate in basis points
    /// @param newLpSharePercent New LP share percentage in basis points
    function setFeeParameters(
        uint256 newSwapFeeRate,
        uint256 newLpSharePercent
    ) external onlyOwner {
        require(newSwapFeeRate > 0 && newSwapFeeRate <= 1000, "Invalid swap fee rate"); // Max 10%
        require(newLpSharePercent > 0 && newLpSharePercent <= 10000, "Invalid LP share percent"); // Max 100%

        swapFeeRate = newSwapFeeRate;
        lpSharePercent = newLpSharePercent;

        emit FeeParametersUpdated(newSwapFeeRate, newLpSharePercent);
    }

    /// @notice Update fee parameters for a specific pool (owner or admin)
    /// @param poolAddress The address of the pool to update
    /// @param newSwapFeeRate New swap fee rate in basis points
    /// @param newLpSharePercent New LP share percentage in basis points
    /// @dev This function allows setting custom fee parameters for individual pools
    /// @dev The pool must be owned by this factory (i.e., created by this factory)
    function setPoolFeeParameters(
        address poolAddress,
        uint256 newSwapFeeRate,
        uint256 newLpSharePercent
    ) external onlyOwner {
        require(poolAddress != address(0), "Zero pool address");
        require(newSwapFeeRate > 0 && newSwapFeeRate <= 1000, "Invalid swap fee rate"); // Max 10%
        require(newLpSharePercent > 0 && newLpSharePercent <= 10000, "Invalid LP share percent"); // Max 100%

        // Verify the pool belongs to this factory
        require(address(Pool(poolAddress).poolFactory()) == address(this), "Pool does not belong to this factory");

        // Call the pool's single setFeeParameters function
        Pool(poolAddress).setFeeParameters(newSwapFeeRate, newLpSharePercent);

        emit PoolFeeParametersUpdated(poolAddress, newSwapFeeRate, newLpSharePercent);
    }

    /// @notice Call sync on all pools or select pools
    /// @param pools Array of pool addresses to sync
    /// @dev If no pools are provided, sync all pools
    /// @dev This function is used to sync the pools after a token transfer
    function syncPools(address[] pools) external onlyOwner {
        address[] memory targetPools = pools;
        if (targetPools.length == 0) {
            targetPools = allPools;
        }
        for (uint256 i = 0; i < targetPools.length; i++) {
            Pool(targetPools[i]).sync();
        }
    }

    /// @notice Call skim on all pools or select pools
    /// @param pools Array of pool addresses to skim
    /// @param to Address to skim the pools to
    /// @dev If no pools are provided, skim all pools
    /// @dev This function is used to skim the pools after a token transfer
    function skimPools(address[] pools, address to) external onlyOwner {
        address[] memory targetPools = pools;
        if (targetPools.length == 0) {
            targetPools = allPools;
        }
        for (uint256 i = 0; i < targetPools.length; i++) {
            Pool(targetPools[i]).skim(to);
        }
    }

    // ============ POOL MANAGEMENT ============

    /// @notice Create a new pool for tokenA/tokenB
    /// @dev After pool creation, the pool should be whitelisted for mint and burn of the LP tokenby the admin registry
    function createPool(address tokenA, address tokenB) external tokensActive(tokenA, tokenB) onlyOwner returns (address pool) {
        require(tokenA != address(0) && tokenB != address(0), "Zero address");
        require(tokenA != tokenB, "Identical addresses");
        require(pools[tokenA][tokenB] == address(0) && pools[tokenB][tokenA] == address(0), "Pool exists");

        // deploy new lp token
        string lpName = ERC20(tokenA).name() + "-" + ERC20(tokenB).name() + " LP Token";
        string lpSymbol = ERC20(tokenA).symbol() + "-" + ERC20(tokenB).symbol() + "-LP";

        address lpTokenAddress = TokenFactory(tokenFactory).createTokenWithInitialOwner(
            lpName,
            "Liquidity Provider Token",
            [],
            [],
            [],
            lpSymbol,
            0,
            18,
            this
        );

        // deploy new pool first
        address thisOwner = owner();
        pool = address(new Proxy(address(new Pool(address(thisOwner))), address(this)));
        Pool(pool).initialize(tokenA, tokenB, lpTokenAddress);
        Pool(pool).transferOwnership(thisOwner);
        Ownable(lpTokenAddress).transferOwnership(thisOwner);

        // update pool registry
        pools[tokenA][tokenB] = pool;
        pools[tokenB][tokenA] = pool; // support both directions
        allPools.push(pool);

        emit NewPool(tokenA, tokenB, pool);

        return pool;
    }

    /// @notice Transfer all pools to a new factory
    /// @param newFactory Address of the new factory
    function transferPoolsToFactory(address newFactory) external onlyOwner {
        for (uint256 i = 0; i < allPools.length; i++) {
            address pool = allPools[i];
            if (pool != address(0)) {
                // Transfer pool to new factory
                Pool(pool).transferPoolToFactory(newFactory);
            }
        }
        emit PoolsMigrated(address(this), newFactory, allPools.length);
    }

    /// @notice Register pools received from another factory
    /// @param poolAddresses Array of pool addresses to register
    function registerPoolsFromFactory(address[] poolAddresses) external onlyOwner {
        for (uint256 i = 0; i < poolAddresses.length; i++) {
            address pool = poolAddresses[i];

            // Verify the pool belongs to this factory
            require(address(Pool(pool).poolFactory()) == address(this), "Pool does not belong to this factory");

            // Get tokenA and tokenB from the pool contract
            Pool poolContract = Pool(pool);
            address tokenA = address(poolContract.tokenA());
            address tokenB = address(poolContract.tokenB());

            // Only register if pool doesn't already exist
            if (pools[tokenA][tokenB] == address(0) && pools[tokenB][tokenA] == address(0)) {
                pools[tokenA][tokenB] = pool;
                pools[tokenB][tokenA] = pool;
                allPools.push(pool);
            }
        }
        emit PoolsMigrated(address(0), address(this), poolAddresses.length);
    }
}

import "../../abstract/ERC20/access/Ownable.sol";

/**
 * @title Proxy
 * @notice Upgradeable proxy pattern implementation that enables smart contract upgradeability
 * @dev Separates contract logic from storage, allowing logic to be upgraded while preserving state
 *
 * Architecture:
 *   User → Proxy (storage) → delegatecall → Logic Contract (code)
 *            ↑                                      ↓
 *            └──────── executes in proxy context ──┘
 *
 * Key Components:
 * - logicContract: Address of the implementation contract containing the actual
 *   business logic
 * - setLogicContract(): Owner-only function to upgrade the logic contract
 * - fallback(): Delegates all function calls to the logic contract using
 *   delegatecall
 *
 * How it works:
 * - When you call a function on the Proxy, the fallback function intercepts it
 * - Using delegatecall, it executes the function in the logic contract's code
 * - Crucially: The execution happens in the Proxy's storage context, not the
 *   logic contract's
 * - This means state variables are stored in the Proxy, while logic is in the
 *   implementation
 *
 * Benefits:
 * - Upgradeability: Fix bugs or add features without changing the contract
 *   address
 * - Storage Preservation: User balances, state variables remain intact across
 *   upgrades
 * - Separation of Concerns: Logic and data are decoupled
 */
contract record Proxy is Ownable {
    address logicContract;

    constructor(address _logicContract, address _initialOwner) Ownable(_initialOwner) {
        logicContract = _logicContract;
    }

    function setLogicContract(address _logicContract) onlyOwner {
        logicContract = _logicContract;
    }

    fallback(variadic args) external returns (variadic) {
        return logicContract.delegatecall(msg.sig, args);
    }
}

