/**
 * FYI: IMPORTANT NOTICE FOR ERC20 REIMPLEMENTATION
 *
 * Anyone planning to modify this Token contract or reimplement ERC20 functionality should read this:
 *
 * 1. This Token contract inherits from ERC20 (../../abstract/ERC20.sol), which is a copy of
 *    OpenZeppelin's ERC20 implementation with some modifications.
 *
 * 2. CRITICAL BEHAVIOR: The current ERC20.sol implementation deviates from the ERC20 standard
 *    in that transfer() and transferFrom() functions ALWAYS REVERT on invalid states
 *    (e.g., insufficient funds) instead of returning false as specified in the ERC20 standard.
 *    This means these functions will either:
 *    - Return true (success), OR
 *    - Throw/revert (failure)
 *    They will NEVER return false.
 *
 * 3. OpenZeppelin's reference implementation follows the same pattern (revert on failure).
 *
 * 4. DEPENDENCY: Other contracts in this codebase leverage this "revert-on-failure" behavior.
 *    They call transfer()/transferFrom() and assume the call will either succeed or revert,
 *    without checking the return value in many cases.
 *
 * 5. BREAKING CHANGE WARNING: If you replace ERC20.sol with an implementation that returns
 *    false on failure (instead of reverting), this will break other contracts that depend
 *    on the current behavior. Many contracts will silently accept failed transfers as successful.
 *
 * 6. Consider this dependency whenever modifying ERC20.sol or Token.sol. Any changes to the
 *    error handling behavior must be coordinated with updates to all dependent contracts.
 */

enum TokenStatus { NULL, PENDING, ACTIVE, LEGACY }

contract record Token is ERC20, Ownable, TokenMetadata, Pausable {
    uint8 public customDecimals;
    TokenStatus public status;
    TokenFactory public tokenFactory;

    event StatusChanged(TokenStatus newStatus);

    modifier onlyTokenFactory() {
        require(msg.sender == address(tokenFactory), "Token: caller is not token factory");
        _;
    }

    modifier whenNotPausedOrOwner() {
        if (paused()) {
            try {
                _checkOwner();
            } catch {
                AdminRegistry admin = AdminRegistry(Ownable(tokenFactory).owner());
                require(admin.whitelist(address(this), msg.sig, _msgSender()), "not whitelisted");
            }
        }
        _;
    }

    constructor(address initialOwner)
        Ownable(initialOwner)
        ERC20("", "")
        TokenMetadata("", [], [], [])
    {}

    /// @dev This initializer may be called only once, during the first initialization of the token.
    function initialize(
        string name_,
        string description_,
        string[] images_,
        string[] files_,
        string[] fileNames_,
        string symbol_,
        uint256 initialSupply_,
        uint8 customDecimals_,
        address tokenCreator_
    ) external onlyOwner {

        // ERC20(name_, symbol_)
        __ERC20_init(name_, symbol_);

        // TokenMetadata(description_, images_, files_, fileNames_)
        _setMetadata(description_, images_, files_, fileNames_);

        customDecimals = customDecimals_;
        status = TokenStatus.PENDING;
        tokenFactory = TokenFactory(msg.sender);
        _mint(tokenCreator_, initialSupply_);

        emit StatusChanged(status);
    }

    function setStatus(uint newStatus) external onlyOwner {
        require(newStatus != uint(status), "Token: New status is the same as the current status");
        require(newStatus != uint(TokenStatus.NULL), "Token: New status is NULL");
        TokenStatus _newStatus = TokenStatus(newStatus);
        status = _newStatus;

        emit StatusChanged(status);
    }

    function setTokenFactory(address _tokenFactory) external onlyTokenFactory {
        tokenFactory = TokenFactory(_tokenFactory);
    }

    function mint(address to, uint256 amount) external onlyOwner {
        _mint(to, amount);
    }

    function burn(address from, uint256 amount) external onlyOwner {
        _burn(from, amount);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    function setMetadata (
        string _description,
        string[] _images,
        string[] _files,
        string[] _fileNames
    ) external onlyOwner {
        _setMetadata(_description, _images, _files, _fileNames);
    }

    function setAttribute(string key, string value) external onlyOwner {
        _setAttribute(key, value);
    }

    function decimals() external view virtual override returns (uint8) {
        return customDecimals;
    }

    function transfer(address to, uint256 value) public override whenNotPausedOrOwner returns (bool) {
        return super.transfer(to, value);
    }

    function transferFrom(address from, address to, uint256 value) public override whenNotPausedOrOwner returns (bool) {
        return super.transferFrom(from, to, value);
    }
}

/**
 * @title TokenFactory
 * @notice Factory pattern contract that standardizes token creation and tracking
 * @dev While tokens are created here, users interact directly with token contracts after creation
 *
 * The factory serves three main purposes:
 * 1. Standardized token creation (owner or admin only)
 * 2. Token registry - track all tokens created by this factory
 * 3. Token validation - verify tokens are active and belong to this factory
 */

// SPDX-License-Identifier: MIT
import "./Token.sol";
import "../../abstract/ERC20/access/Ownable.sol";
import "../Proxy/Proxy.sol";

/// @notice Token factory contract
contract record TokenFactory is Ownable {

    // ============ EVENTS ============

    /// @notice Event emitted when a new token is created
    event TokenCreated(address token, address creator, string name, string symbol);

    /// @notice Event emitted when tokens are migrated
    event TokensMigrated(address oldFactory, address newFactory, uint256 tokenCount);

    /// @notice Event emitted when tokens are registered
    event TokensRegistered(uint256 tokenCount);

    // ============ STATE VARIABLES ============

    /// @notice Mapping of token addresses to factory token status
    mapping(address => bool) public isFactoryToken;

    /// @notice Array of all token addresses
    address[] public record allTokens;

    // ============ CONSTRUCTOR ============

    /// @notice Constructor
    /// @param initialOwner The initial owner of the contract
    constructor(address initialOwner) Ownable(initialOwner) {
    }

    // ============ TOKEN MANAGEMENT ============

    /// @notice Create a new token
    /// @param _name Token name
    /// @param _description Token description
    /// @param _images Array of image URLs
    /// @param _files Array of file URLs
    /// @param _fileNames Array of file names
    /// @param _symbol Token symbol
    /// @param _initialSupply Initial token supply
    /// @param _customDecimals Token decimals
    /// @return Address of the created token
    function createToken(
        string _name,
        string _description,
        string[] _images,
        string[] _files,
        string[] _fileNames,
        string _symbol,
        uint256 _initialSupply,
        uint8 _customDecimals
    ) external onlyOwner returns (address) {
        return createTokenWithInitialOwner(
            _name,
            _description,
            _images,
            _files,
            _fileNames,
            _symbol,
            _initialSupply,
            _customDecimals,
            msg.sender
        );
    }

    function createTokenWithInitialOwner(
        string _name,
        string _description,
        string[] _images,
        string[] _files,
        string[] _fileNames,
        string _symbol,
        uint256 _initialSupply,
        uint8 _customDecimals,
        address _initialOwner
    ) public onlyOwner returns (address) {
        // Create new token with msg.sender as the token creator
        Token newToken = Token(address(new Proxy(address(new Token(_initialOwner)), address(this))));
        newToken.initialize(
            _name,
            _description,
            _images,
            _files,
            _fileNames,
            _symbol,
            _initialSupply,
            _customDecimals,
            _initialOwner
        );
        newToken.transferOwnership(_initialOwner);

        // Register the token
        address tokenAddress = address(newToken);
        isFactoryToken[tokenAddress] = true;
        allTokens.push(tokenAddress);

        emit TokenCreated(tokenAddress, msg.sender, _name, _symbol);
        return tokenAddress;
    }

    /// @notice Check if a token is active and belongs to this factory
    /// @param token Token address to check
    /// @return True if token is active and belongs to this factory
    function isTokenActive(address token) external view returns (bool) {
        return Token(token).status() == TokenStatus.ACTIVE && isFactoryToken[token];
    }

    /// @notice Migrate tokens to a new factory
    /// @param newFactory Address of the new factory
    function migrateTokensToFactory(address newFactory) external onlyOwner {
        for (uint256 i = 0; i < allTokens.length; i++) {
            address tokenAddr = allTokens[i];
            Token(tokenAddr).setTokenFactory(newFactory);
        }
        emit TokensMigrated(address(this), newFactory, allTokens.length);
    }

    /// @notice Register tokens that were migrated from another factory
    /// @param tokens Array of token addresses to register
    function registerMigratedTokens(address[] tokens) external onlyOwner {
        for (uint256 i = 0; i < tokens.length; i++) {
            isFactoryToken[tokens[i]] = true;
            allTokens.push(tokens[i]);
        }
        emit TokensRegistered(tokens.length);
    }
}

contract TokenMetadata {
    string description;
    string[] record images;
    string[] record files;
    string[] record fileNames;

    mapping(string => string) public record attributes;

    constructor(
        string _description,
        string[] _images,
        string[] _files,
        string[] _fileNames
    ){
        description = _description;
        images = _images;
        files = _files;
        fileNames = _fileNames;
    }

    function _setMetadata(
        string _description,
        string[] _images,
        string[] _files,
        string[] _fileNames
    ) internal {
        description = _description;
        images = _images;
        files = _files;
        fileNames = _fileNames;
    }

    function _setAttribute(
        string key,
        string value
    ) internal {
        attributes[key] = value;
    }
}

